(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,76488,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"Innovation Driven","desc":"Integrate cutting-edge AI into every creative project—break boundaries and unlock endless possibilities."},"design":{"title":"Design Aesthetics","desc":"Pursue exceptional visual experiences—every pixel is carefully crafted to deliver stunning beauty."},"quality":{"title":"Quality Assurance","desc":"A rigorous quality system—each deliverable reflects our relentless pursuit of excellence."},"experience":{"title":"Experience First","desc":"Refine every step—from user journey to interaction details—so the product feels clearer, smoother, and easier to use."},"maintenance":{"title":"Ongoing Maintenance","desc":"Launch is just the beginning—continuous fixes, optimizations, and iterations keep your experience improving over time."},"security":{"title":"Security & Privacy","desc":"Protecting your data is our top priority. We use industry-leading security measures to ensure your information is safe and confidential."}},"feedbackButton":"Send Feedback","feedbackCardTitle":"Share your feedback or inspiration","feedbackCardDesc":["You’re always welcome to report issues or send your ideas and suggestions. We read every message and keep iterating to make the product better. Share any friction you hit and what you’re hoping for, or what you’d like us to add or improve next. If you can, include your use case, screenshots, or steps to reproduce—this helps us diagnose and improve faster.","If you’re interested in creative collaboration or joining the team, feel free to reach out anytime."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"Generate usable 3D models from a single image, preview in real time on mobile, and export to GLB/STL. No 3D experience needed—true what-you-see-is-what-you-get.","description":"Shoot → Generate → Preview → Export. Done in one go.","details":{"intro":"3D-PaiLiTi lets you turn a single image into a usable 3D model, preview it in real time on mobile, and export to GLB/STL—no 3D experience required.","featureTitle":"Key features","items":["One-click image-to-3D: import a photo or image to generate a 3D model automatically (great for editable drafts and fast iteration).","WYSIWYG preview: built-in 3D viewer with rotate/zoom and multiple lighting presets.","Multiple export formats: export to GLB/STL for continued editing in common engines and tools.","Task queue & history: automatically records jobs so you can download and manage anytime.","Offline caching: generated models can be viewed offline.","Multilingual UI: supports multiple languages."]}},"koala":{"title":"Koala Haventree","subtitle":"A cozy, private space to let your feelings breathe.\\nChat when you need company, write when you need clarity, and use gentle tools to release what’s been stuck inside.","description":"A gentle place for your feelings to land.","details":{"sections":[{"title":"🗣️ Chat & Reflect (AI-generated)","items":["Talk through your thoughts in a calm, supportive space","Get gentle prompts to help you name what you feel and why it matters"]},{"title":"🕳️ The Tree Hole (Vent privately)","items":["Drop your worries into a private “tree hole” anytime","No judgment—just a place to unload and move forward"]},{"title":"🎴 Mood Cards","items":["Draw emotion cards for quick insight and encouragement","Small reminders that help you reframe and keep going"]},{"title":"📓 Photo Journal","items":["Write diary entries and take a photo when you want to capture the moment","Or upload a photo from your device to keep memories together","Build your own timeline of feelings, stories, and growth"]},{"title":"📊 Weekly Insights","items":["Simple summaries based on your in-app activity (e.g., journaling/venting trends)","Helpful for noticing patterns—without pressure"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"Generate usable 3D models from a single image, preview in real time on mobile, and export to GLB/STL. No 3D experience needed—true what-you-see-is-what-you-get.","description":"3D-PaiLiTi is an innovative application that leverages advanced AI technology to transform your 2D images into high-quality 3D models. Simply upload a photo, and our intelligent algorithms will automatically generate a detailed 3D model that you can preview in real-time and export for use in various projects. Whether you\'re a designer, developer, or hobbyist, 3D-PaiLiTi streamlines your creative workflow and opens up new dimensions of possibility.","storyIntro":{"title":"3D-PaiLiTi — Story","paragraphs":["From a small spark of an idea to something that truly comes alive on your phone, the journey has been full of twists—roadblocks, mistakes, and little moments of joy.","For me, it’s more than an app; it’s a learning journey of turning ideas into reality. It may not be perfect yet, but every detail carries our care. I hope you can feel that sincerity and warmth."]},"features":{"title":"Features","items":{"ai_modeling":{"title":"AI Smart Modeling","description":"Advanced AI algorithms to convert 2D images into high-quality 3D models with one click.","icon":"🎨"},"export":{"title":"Multi-format Export","description":"Supports mainstream 3D formats like GLB and STL to meet different needs.","icon":"📦"},"preview":{"title":"Online Preview","description":"Real-time 360° model viewing with switchable environments.","icon":"👁️"},"optimization":{"title":"AI Optimization","description":"Intelligent image modification and stylization for more stable results.","icon":"🔄"},"share":{"title":"One-click Sharing","description":"Easily share your 3D creations on social media or with your team.","icon":"🌐"},"fast":{"title":"Fast Generation","description":"Optimized cloud process to quickly obtain usable 3D models.","icon":"⚡"}}},"users":{"title":"Target Audience","tags":[{"title":"Game Developers","icon":"🎮"},{"title":"3D Modelers","icon":"🧊"},{"title":"Architects","icon":"🏛️"},{"title":"Product Designers","icon":"💡"},{"title":"Model Enthusiasts","icon":"🧩"},{"title":"Creative Workers","icon":"🎨"},{"title":"Educators","icon":"🎓"}]},"productIntro":{"sectionTitle":"Core Features","items":["One-click image-to-3D: import a photo or image and automatically generate a 3D model for fast iteration and refinement.","WYSIWYG preview: built-in 3D viewer supports rotation, zooming, and multiple lighting presets.","Multiple export formats: export to GLB/STL for continued editing in popular engines and slicers.","Task queue and history: jobs are recorded automatically so you can re-download and manage them anytime.","Offline caching: generated models stay viewable without a network connection.","Multilingual UI: supports Chinese, English, Malay, Japanese, Korean, and more languages."],"noteTitle":"Important Note","noteBody":"This app focuses on quick one-click creation of editable base models. Automated generation may not reach the level of handcrafted detail; for higher precision and better topology, keep refining in your preferred 3D editing software."}},"koalaPage":{"title":"Koala Haventree","subtitle":"A gentle place for your feelings to land.","description":"Koala Haventree is a unique mobile game that provides a tranquil and comforting space for relaxation and self-reflection. In this peaceful world, you can grow your own \'emotion trees,\' interact with gentle forest creatures, and create a personalized haven. With its soothing art style and calming gameplay, Koala Haventree offers a gentle escape from the hustle and bustle of daily life, helping you find moments of peace and mindfulness.","storyIntro":{"title":"Koala Haventree — Story","paragraphs":["This time, we’re taking our first serious shot at polishing an emotionally-aware AI companion. The hardest part wasn’t making it “more talkative”—it was teaching it boundaries: to be more human, to hold space for your feelings, and to make it safe for you to open up.","You can switch between different roles as needed, so it can speak with a more human tone—joking with you when it’s right, and keeping a gentle sense of distance when it should. We often stop and ask ourselves: is it accompanying you, or interrupting you? Many decisions weren’t about doing “more,” but about putting companionship first—showing up when it should, and staying quietly with you when that’s better.","What we want to protect is simple: an app that understands you without judging you—only offering, when you need it, a calm and comfortable place to vent, to talk, and to record your feelings."]},"features":{"title":"Features","items":{"emotion_card":{"title":"Emotion Cards","description":"Draw your exclusive emotion card to explore every fluctuation of your heart.","icon":"🃏"},"ai_chat":{"title":"AI Chat","description":"Talk to your cute koala companion anytime and share your joys and sorrows.","icon":"💬"},"venting_hole":{"title":"Tree Hollow","description":"Safely entrust all unhappiness and secrets to the tree hollow to release your mind.","icon":"🌳"},"diary":{"title":"Journaling","description":"Record daily life moments and mood stories to treasure your exclusive memories.","icon":"✍️"},"ai_report":{"title":"AI Report","description":"Generate professional emotional reports based on your records to help you understand yourself better.","icon":"📊"},"achievements":{"title":"Achievements","description":"Unlock unique achievements by collecting cards, chatting, and recording.","icon":"🏆"}}},"users":{"title":"Target Audience","tags":[{"title":"Passionate about Journaling","icon":"📒"},{"title":"Focus on Emotional Wellness","icon":"❤️"},{"title":"Fast-paced Lifestyle","icon":"⚡"},{"title":"Seeking Stress Relief","icon":"🍃"},{"title":"Longing for Companionship","icon":"🧸"},{"title":"Pursuing Inner Peace","icon":"🧘"}]},"productIntro":{"mainTitle":"Core features","sections":[{"title":"Chat & Reflect (AI-generated)","items":["Talk through your thoughts in a calm, supportive space","Get gentle prompts to help you name what you feel and why it matters"]},{"title":"The Tree Hole (Vent privately)","items":["Drop your worries into a private “tree hole” anytime","No judgment—just a place to unload and move forward"]},{"title":"Mood Cards","items":["Draw emotion cards for quick insight and encouragement","Small reminders that help you reframe and keep going"]},{"title":"Photo Journal","items":["Write diary entries and take a photo when you want to capture the moment","Or upload a photo from your device to keep memories together","Build your own timeline of feelings, stories, and growth"]},{"title":"Weekly Insights","items":["Simple summaries based on your in-app activity (e.g., journaling/venting trends)","Helpful for noticing patterns—without pressure"]}],"noteTitle":"Important note","noteBody":"Koala Haventree provides supportive, AI-generated content and journaling tools. It is not a medical app and does not provide diagnosis or treatment. If you’re in danger or considering self-harm, please contact local emergency services or a trusted professional immediately."}},"footer":{"privacyPolicy":"Privacy Policy","termsOfService":"Terms of Service"}}'))},35992,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"ابتكار مدفوع","desc":"نمزج أحدث تقنيات الذكاء الاصطناعي في كل مشروع إبداعي—لتجاوز الحدود وفتح إمكانيات جديدة."},"design":{"title":"جماليات التصميم","desc":"نسعى لتجربة بصرية استثنائية—كل بكسل مُصاغ بعناية."},"quality":{"title":"ضمان الجودة","desc":"نظام جودة صارم—كل مخرج يعكس سعينا الدائم نحو التميّز."},"experience":{"title":"التجربة أولاً","desc":"من مسار المستخدم إلى تفاصيل التفاعل—نصقل كل شيء ليصبح أوضح وأسلس وأسهل."},"maintenance":{"title":"صيانة مستمرة","desc":"الإطلاق مجرد بداية—إصلاحات وتحسينات وتكرار مستمر لتطوير التجربة مع الوقت."},"security":{"title":"الأمان والخصوصية","desc":"حماية بياناتك هي أولويتنا القصوى. نحن نستخدم تدابير أمنية رائدة في الصناعة لضمان أن تظل معلوماتك آمنة وسرية."}},"feedbackButton":"إرسال ملاحظات","feedbackCardTitle":"شاركنا رأيك أو أفكارك","feedbackCardDesc":["نرحّب دائمًا بملاحظاتك—سواء للإبلاغ عن مشكلة أو لإرسال أفكارك واقتراحاتك. نقرأ كل رسالة بعناية ونواصل التحسين بشكل مستمر لجعل المنتج أفضل. شاركنا ما يعيقك أثناء الاستخدام وما تتوقعه، أو ما تود إضافته أو تحسينه مستقبلًا. ونرحّب جدًا بإرفاق سياق الاستخدام، لقطات شاشة، أو خطوات لإعادة المشكلة—فهذا يساعدنا على التشخيص والتحسين بسرعة أكبر.","وإذا كنت مهتمًا بتعاون إبداعي أو بالانضمام إلى الفريق، فلا تتردد في التواصل معنا في أي وقت."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"أنشئ نماذج 3D قابلة للاستخدام من صورة واحدة، مع معاينة فورية على الهاتف والتصدير إلى GLB/STL بسهولة. لا حاجة لخبرة ثلاثية الأبعاد—ما تراه هو ما تحصل عليه.","description":"تصوير → إنشاء → معاينة → تصدير. مرة واحدة تكفي.","details":{"intro":"يحوّل 3D-PaiLiTi صورة واحدة إلى نموذج 3D قابل للاستخدام، مع معاينة فورية على الهاتف وتصدير GLB/STL—دون خبرة ثلاثية الأبعاد.","featureTitle":"الميزات الأساسية","items":["تحويل صورة إلى 3D بنقرة واحدة: استورد صورة ليتم إنشاء نموذج تلقائيًا (مناسب كمسودة قابلة للتعديل).","معاينة WYSIWYG: عارض 3D مدمج مع تدوير/تكبير وإعدادات إضاءة متعددة.","صيغ تصدير متعددة: التصدير إلى GLB/STL لمتابعة التحرير في أدوات شائعة.","قائمة انتظار وسجل: يتم حفظ المهام تلقائيًا للتنزيل والإدارة لاحقًا.","تخزين مؤقت دون اتصال: يمكن عرض النماذج المُنشأة دون إنترنت.","واجهة متعددة اللغات: دعم لعدة لغات."]}},"koala":{"title":"Koala Haventree","subtitle":"مساحة دافئة وخاصة لتتنفس فيها مشاعرك.\\nتحدّث حين تحتاج رفقة، واكتب حين تحتاج وضوحًا، واستخدم أدوات لطيفة لتفريغ ما علق بداخلك.","description":"مكان لطيف لتهدأ فيه مشاعرك.","details":{"sections":[{"title":"🗣️ Chat & Reflect (مُولّد بالذكاء الاصطناعي)","items":["تحدّث عن أفكارك في مساحة هادئة وداعمة","إشارات لطيفة تساعدك على تسمية ما تشعر به ولماذا يهم"]},{"title":"🕳️ The Tree Hole (تفريغ بشكل خاص)","items":["ضع همومك في «حفرة الشجرة» الخاصة في أي وقت","دون أحكام—مجرد مساحة للتنفيس والمتابعة"]},{"title":"🎴 Mood Cards","items":["اسحب بطاقات المشاعر للحصول على لمحة سريعة وتشجيع","تذكيرات صغيرة تساعدك على إعادة التأطير والاستمرار"]},{"title":"📓 يوميات الصور","items":["اكتب مذكراتك والتقط صورة عندما تريد توثيق اللحظة","أو ارفع صورة من جهازك لحفظ الذكريات معًا","ابنِ خطّك الزمني الخاص للمشاعر والقصص والنمو"]},{"title":"📊 رؤى أسبوعية","items":["ملخصات بسيطة حسب نشاطك داخل التطبيق (مثل اتجاهات المذكرات/التنفيس)","مفيدة لاكتشاف الأنماط—دون ضغط"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"أنشئ نماذج ثلاثية الأبعاد قابلة للاستخدام من صورة واحدة، اعرضها مباشرة على الهاتف، وصدّرها إلى GLB/STL. دون خبرة 3D—تجربة WYSIWYG حقيقية.","description":"3D-PaiLiTi تطبيق مبتكر يستخدم ذكاءً اصطناعيًا متقدمًا لتحويل صورك ثنائية الأبعاد إلى نماذج ثلاثية الأبعاد عالية الجودة. ارفع صورة واحدة ليتم إنشاء نموذج مفصل يمكنك معاينته وتصديره. مناسب للمصممين والمطورين والهواة.","storyIntro":{"title":"3D-PaiLiTi — قصة","paragraphs":["من شرارة فكرة أولى إلى شيء ينبض بالحياة على هاتفك، كانت الرحلة مليئة بالتحديات — تعثّر، أخطاء، ولحظات فرح صغيرة.","بالنسبة لي، هذا أكثر من مجرد تطبيق؛ إنه رحلة تعلّم لتحويل الأفكار إلى واقع. قد لا يكون مثاليًا بعد، لكن كل تفصيل يحمل عنايتنا. آمل أن تشعر بتلك الجدية والدفء."]},"features":{"title":"الميزات","items":{"ai_modeling":{"title":"نمذجة بالذكاء الاصطناعي","description":"تحويل 2D إلى 3D بنقرة واحدة بخوارزميات متقدمة.","icon":"🎨"},"export":{"title":"تصدير متعدد الصيغ","description":"دعم GLB وSTL وغيرها من الصيغ الشائعة.","icon":"📦"},"preview":{"title":"معاينة","description":"عرض 360° فوري مع بيئات قابلة للتبديل.","icon":"👁️"},"optimization":{"title":"تحسين بالذكاء الاصطناعي","description":"تعديلات ذكية للحصول على نتائج أكثر ثباتًا.","icon":"🔄"},"share":{"title":"مشاركة","description":"شارك نتائجك ثلاثية الأبعاد بسهولة.","icon":"🌐"},"fast":{"title":"توليد سريع","description":"عملية سحابية محسّنة للحصول على نماذج قابلة للاستخدام بسرعة.","icon":"⚡"}}},"users":{"title":"مناسب لـ","tags":[{"title":"مطورو ألعاب","icon":"🎮"},{"title":"صنّاع 3D","icon":"🧊"},{"title":"معماريون","icon":"🏛️"},{"title":"مصممو منتجات","icon":"💡"},{"title":"هواة النمذجة","icon":"🧩"},{"title":"مبدعون","icon":"🎨"},{"title":"التعليم","icon":"🎓"}]},"productIntro":{"sectionTitle":"الميزات الأساسية","items":["تحويل الصورة إلى 3D بنقرة واحدة: استورد صورة وأنشئ نموذجًا ثلاثي الأبعاد تلقائيًا للتكرار والتنقيح السريع.","معاينة WYSIWYG: يعرض العارض الثلاثي الأبعاد المدمج الدوران، التكبير، وعدة إعدادات إضاءة.","تنسيقات تصدير متعددة: صدّر إلى GLB/STL لمتابعة التحرير في المحركات والبرامج الشائعة.","قائمة انتظار المهام والسجل: تُحفظ المهام تلقائيًا لإعادة تنزيلها وإدارتها في أي وقت.","ذاكرة تخزين مؤقت خارج الإنترنت: تظل النماذج القابلة للتوليد مرئية حتى بدون اتصال.","واجهة متعددة اللغات: تدعم الصينية والإنجليزية والملايو واليابانية والكورية وغيرها."],"noteTitle":"ملاحظة مهمة","noteBody":"يركز التطبيق على إنشاء نماذج أساسية قابلة للتعديل بنقرة واحدة بسرعة. قد لا توفر الأتمتة نفس مستوى التفاصيل اليدوية؛ إذا كنت بحاجة لدقة أعلى أو طوبولوجيا أفضل، تابع التنقيح في برنامج تحرير ثلاثي الأبعاد تختاره."}},"koalaPage":{"title":"Koala Haventree","subtitle":"مكان لطيف لتهدأ فيه مشاعرك.","description":"Koala Haventree لعبة موبايل فريدة تمنحك مساحة هادئة ومريحة للاسترخاء والتأمل الذاتي. يمكنك تنمية «أشجار المشاعر»، والتفاعل مع مخلوقات الغابة، وصنع ملاذك الخاص. بأسلوب فني مهدئ وتجربة لعب لطيفة لتجد لحظات من السكينة.","storyIntro":{"title":"Koala Haventree — قصة","paragraphs":["هذه المرة هي محاولتنا الأولى لصقل تطبيق ذكاء اصطناعي يحمل حسًا عاطفيًا. أكثر ما بذلنا فيه جهدًا لم يكن «جعله يتكلم أكثر»، بل تعليمه الحدود والاتزان: أن يكون أكثر إنسانية، وأكثر مراعاة، وأن يستطيع احتواء مشاعرك لتشعر بالأمان عند البوح.","يمكنك تبديل الأدوار حسب حاجتك ليحادثك بنبرة أقرب للإنسان: يمزح حين يكون ذلك مناسبًا، ويعرف كيف يحافظ على المسافة عند اللزوم—حاضر عندما تحتاج كلمة إضافية، وصامت يرافقك عندما يكون الهدوء أفضل. كثيرًا ما نسأل أنفسنا: هل يرافقك أم يزعجك؟ لذا لم تكن خيارات كثيرة لعمل «المزيد»، بل لجعل المرافقة هي الأساس: يظهر حين يجب، ويهدأ حين يكون ذلك أفضل.","نريد أن نحافظ على أمر واحد: بناء تطبيق يفهمك دون أن يصدر أحكامًا بدلًا منك—ويمنحك عندما تحتاج، مكانًا هادئًا ومريحًا لتتنفّس، وتفضفض، وتكتب ما تشعر به."]},"features":{"title":"الميزات","items":{"emotion_card":{"title":"بطاقات المشاعر","description":"اسحب بطاقة لتستكشف ما تشعر به.","icon":"🃏"},"ai_chat":{"title":"دردشة بالذكاء الاصطناعي","description":"تحدث مع رفيق الكوالا في أي وقت.","icon":"💬"},"venting_hole":{"title":"حفرة الشجرة","description":"أودِع همومك وأسرارك بأمان لتخفيف العبء.","icon":"🌳"},"diary":{"title":"اليوميات","description":"سجّل لحظاتك ومشاعرك لتحفظ ذكرياتك.","icon":"✍️"},"ai_report":{"title":"تقرير بالذكاء الاصطناعي","description":"ملخصات تساعدك على فهم نفسك بشكل أفضل.","icon":"📊"},"achievements":{"title":"الإنجازات","description":"افتح إنجازات فريدة عبر الجمع والدردشة والتسجيل.","icon":"🏆"}}},"users":{"title":"مناسب لـ","tags":[{"title":"محبو التدوين","icon":"📒"},{"title":"العناية بالمشاعر","icon":"❤️"},{"title":"وتيرة حياة سريعة","icon":"⚡"},{"title":"تخفيف الضغط","icon":"🍃"},{"title":"الحاجة لرفقة","icon":"🧸"},{"title":"السعي للسلام الداخلي","icon":"🧘"}]},"productIntro":{"mainTitle":"الميزات الرئيسية","sections":[{"title":"الدردشة والتأمل (مدعوم بالذكاء الاصطناعي)","items":["تحدث عن أفكارك في مساحة هادئة وداعمة","اشارات لطيفة تساعدك على تسمية مشاعرك ولماذا تهم"]},{"title":"حفرة الشجرة (تفريغ خاص)","items":["ضع همومك في «حفرة الشجرة» الخاصة متى شئت","دون أحكام، مجرد مكان للتنفيس والمضي قدمًا"]},{"title":"بطاقات المزاج","items":["اسحب بطاقات المشاعر لتلقي نظرة سريعة وتشجيع","تذكيرات بسيطة تساعدك على إعادة صياغة تفكيرك والاستمرار"]},{"title":"دفتر الصور","items":["اكتب يومياتك والتقط صورة عند رغبتك في توثيق اللحظة","أو ارفع صورة من جهازك لجمع الذكريات معًا","كون خطًا زمنيًا خاصًا بمشاعرك وقصصك ونموك"]},{"title":"رؤى أسبوعية","items":["تلخيصات بسيطة مبنية على نشاطك داخل التطبيق (مثل الاتجاهات في اليوميات/التفريغ)","مفيدة لاكتشاف الأنماط بدون ضغط"]}],"noteTitle":"ملاحظة مهمة","noteBody":"Koala Haventree يقدم محتوى داعمًا ناتجًا عن الذكاء الاصطناعي وأدوات تدوين، لكنه ليس تطبيقًا طبيًا ولا يوفر تشخيصًا أو علاجًا. إذا كنت في خطر أو تفكر في إيذاء نفسك، فاتصل فورًا بخدمات الطوارئ المحلية أو بأخصائي موثوق."}},"footer":{"privacyPolicy":"سياسة الخصوصية","termsOfService":"شروط الخدمة"}}'))},67091,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"Innovationsgetrieben","desc":"Wir integrieren modernste KI in jedes kreative Projekt – sprengen Grenzen und eröffnen neue Möglichkeiten."},"design":{"title":"Designästhetik","desc":"Wir streben nach herausragenden visuellen Erlebnissen – jedes Pixel ist sorgfältig gestaltet."},"quality":{"title":"Qualitätssicherung","desc":"Ein strenges Qualitätsverfahren – jedes Ergebnis steht für unseren Anspruch auf Exzellenz."},"experience":{"title":"Erlebnis im Fokus","desc":"Vom Nutzerfluss bis zu Interaktionsdetails – wir feilen so lange, bis es klar, flüssig und einfach nutzbar ist."},"maintenance":{"title":"Kontinuierliche Pflege","desc":"Nach dem Launch geht’s weiter: Fixes, Optimierungen und Iterationen – damit das Produkt langfristig besser wird."},"security":{"title":"Sicherheit & Datenschutz","desc":"Der Schutz Ihrer Daten hat für uns oberste Priorität. Wir verwenden branchenführende Sicherheitsmaßnahmen, um sicherzustellen, dass Ihre Informationen sicher und vertraulich sind."}},"feedbackButton":"Feedback senden","feedbackCardTitle":"Teile uns deine Gedanken mit","feedbackCardDesc":["Du kannst uns jederzeit Probleme melden oder Ideen und Vorschläge schicken. Wir lesen jede Rückmeldung und verbessern das Produkt kontinuierlich. Teile Hürden im Alltag und deine Erwartungen – oder nenne Funktionen und Verbesserungen, die du dir wünschst. Nutzungs­kontext, Screenshots oder Repro‑Schritte helfen uns, schneller zu reagieren.","Wenn du Interesse an kreativer Zusammenarbeit hast oder unserem Team beitreten möchtest, melde dich gern jederzeit."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"Erzeuge nutzbare 3D-Modelle aus einem einzigen Bild, live auf dem Handy in der Vorschau und als GLB/STL exportieren. Keine 3D‑Vorkenntnisse nötig – WYSIWYG.","description":"Aufnehmen → Generieren → Vorschau → Export. Alles in einem Durchgang.","details":{"intro":"3D-PaiLiTi verwandelt ein einzelnes Bild in ein nutzbares 3D‑Modell, bietet Echtzeit‑Vorschau auf dem Handy und Export als GLB/STL – ohne 3D‑Vorkenntnisse.","featureTitle":"Kernfunktionen","items":["One‑Click Image‑to‑3D: Foto/Bild importieren und automatisch ein 3D‑Modell erzeugen (ideal als editierbarer Entwurf).","WYSIWYG‑Vorschau: integrierter 3D‑Viewer mit Drehen/Zoomen und Licht‑Presets.","Mehrere Exportformate: GLB/STL für die Weiterbearbeitung in gängigen Tools.","Warteschlange & Verlauf: Jobs werden automatisch protokolliert.","Offline‑Cache: generierte Modelle können offline angesehen werden.","Mehrsprachige UI: unterstützt mehrere Sprachen."]}},"koala":{"title":"Koala Haventree","subtitle":"Ein gemütlicher, privater Raum, in dem deine Gefühle durchatmen können.\\nChatte, wenn du Gesellschaft brauchst, schreibe, wenn du Klarheit willst, und nutze sanfte Tools, um feststeckende Dinge loszulassen.","description":"Ein sanfter Ort, an dem Gefühle landen dürfen.","details":{"sections":[{"title":"🗣️ Chat & Reflect (KI‑generiert)","items":["Sprich deine Gedanken in einem ruhigen, unterstützenden Raum durch","Sanfte Impulse helfen dir, zu benennen, was du fühlst – und warum es zählt"]},{"title":"🕳️ Das Baumloch (privat abladen)","items":["Wirf deine Sorgen jederzeit in ein privates „Baumloch“","Ohne Urteil – einfach ein Ort zum Loslassen und Weitergehen"]},{"title":"🎴 Stimmungskarten","items":["Ziehe Emotionskarten für schnellen Zuspruch und neue Perspektiven","Kleine Erinnerungen, die beim Umdenken helfen"]},{"title":"📓 Foto‑Tagebuch","items":["Schreibe Einträge und mache ein Foto, wenn du den Moment festhalten willst","Oder lade ein Foto vom Gerät hoch, um Erinnerungen zusammenzuführen","Baue deine eigene Timeline aus Gefühlen, Geschichten und Wachstum"]},{"title":"📊 Wöchentliche Einblicke","items":["Einfache Zusammenfassungen anhand deiner Aktivität (z. B. Tagebuch-/Abladen‑Trends)","Hilft Muster zu erkennen – ohne Druck"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"Erzeuge aus einem einzigen Bild nutzbare 3D-Modelle, sieh sie in Echtzeit auf dem Smartphone an und exportiere als GLB/STL. Kein 3D‑Vorwissen nötig – echtes WYSIWYG.","description":"3D-PaiLiTi nutzt fortschrittliche KI, um 2D‑Bilder in hochwertige 3D‑Modelle zu verwandeln. Lade einfach ein Foto hoch – die Algorithmen erzeugen automatisch ein detailliertes Modell, das du in Echtzeit ansehen und exportieren kannst. Ob Designer:in, Entwickler:in oder Hobbyist:in – 3D-PaiLiTi beschleunigt deinen Workflow und eröffnet neue Möglichkeiten.","storyIntro":{"title":"3D-PaiLiTi — Einblick","paragraphs":["Von einer ersten Idee bis zu etwas, das auf dem Smartphone wirklich lebendig wird: Der Weg war voller Wendungen – Hürden, Fehler und kleine Momente der Freude.","Für mich ist es mehr als nur eine App; es ist eine Lernreise, Ideen in Realität zu verwandeln. Vielleicht noch nicht perfekt, aber jedes Detail trägt unsere Sorgfalt. Ich hoffe, du spürst diese Ernsthaftigkeit und Wärme."]},"features":{"title":"Features","items":{"ai_modeling":{"title":"KI‑Modellierung","description":"Fortschrittliche KI wandelt 2D‑Bilder mit einem Klick in 3D‑Modelle um.","icon":"🎨"},"export":{"title":"Mehrfach‑Export","description":"Export als GLB/STL und weitere gängige Formate.","icon":"📦"},"preview":{"title":"Live‑Vorschau","description":"360°‑Ansicht in Echtzeit mit umschaltbaren Umgebungen.","icon":"👁️"},"optimization":{"title":"KI‑Optimierung","description":"Stabilere Ergebnisse durch intelligente Bildanpassung und Stil‑Optionen.","icon":"🔄"},"share":{"title":"Teilen","description":"Teile deine 3D‑Ergebnisse einfach mit Team oder Social Media.","icon":"🌐"},"fast":{"title":"Schnelle Generierung","description":"Optimierter Cloud‑Prozess für schnelle, nutzbare Modelle.","icon":"⚡"}}},"users":{"title":"Zielgruppe","tags":[{"title":"Game‑Entwickler:innen","icon":"🎮"},{"title":"3D‑Creator","icon":"🧊"},{"title":"Architekt:innen","icon":"🏛️"},{"title":"Produktdesign","icon":"💡"},{"title":"Modell‑Fans","icon":"🧩"},{"title":"Kreativschaffende","icon":"🎨"},{"title":"Lehrkräfte","icon":"🎓"}]},"productIntro":{"sectionTitle":"Kernfunktionen","items":["Ein-Klick-Bild-zu-3D: Lade ein Foto oder Bild hoch und generiere automatisch ein 3D-Modell für schnelles Iterieren und Feintuning.","WYSIWYG-Vorschau: Der integrierte 3D-Viewer unterstützt Rotation, Zoom und mehrere Lichtvorgaben.","Mehrere Exportformate: Exportiere als GLB/STL, um in beliebten Engines und Slicern weiterzuarbeiten.","Aufgabenwarteschlange & Verlauf: Aufgaben werden automatisch gespeichert, damit du sie jederzeit erneut herunterladen und verwalten kannst.","Offline-Cache: Generierte Modelle bleiben auch ohne Netzverbindung sichtbar.","Mehrsprachige Oberfläche: Unterstützt Chinesisch, Englisch, Malaiisch, Japanisch, Koreanisch und weitere Sprachen."],"noteTitle":"Wichtiger Hinweis","noteBody":"Die App fokussiert sich auf die schnelle Erstellung editierbarer Basismodelle mit einem Klick. Automatische Generierung erreicht möglicherweise nicht das Detailniveau handgefertigter Modelle. Für höhere Präzision und bessere Topologie solltest du in deiner bevorzugten 3D-Software weiter nachbearbeiten."}},"koalaPage":{"title":"Koala Haventree","subtitle":"Ein sanfter Ort, an dem Gefühle landen dürfen.","description":"Koala Haventree ist ein einzigartiges Mobile‑Spiel, das einen ruhigen, tröstlichen Raum für Entspannung und Selbstreflexion bietet. In dieser friedlichen Welt kannst du „Emotionsbäume“ wachsen lassen, mit sanften Waldbewohnern interagieren und dir ein persönliches Refugium schaffen. Mit seinem beruhigenden Stil hilft Koala Haventree, im Alltag kurze Momente der Ruhe zu finden.","storyIntro":{"title":"Koala Haventree — Einblick","paragraphs":["Diesmal wagen wir zum ersten Mal den Feinschliff an einer emotionalen KI‑Anwendung. Die größte Arbeit steckte nicht darin, sie „gesprächiger“ zu machen, sondern ihr Grenzen beizubringen: menschlicher, achtsamer – damit sie deine Gefühle besser auffängt und du dich sicher öffnen kannst.","Du kannst je nach Bedarf zwischen Rollen wechseln, sodass sie in einem menschlicheren Ton mit dir spricht – auch mal scherzt, aber stets mit Gefühl für das richtige Maß: Wenn ein Satz mehr hilft, ist sie da; wenn Stille besser ist, drängt sie sich nicht auf. Wir fragen uns oft: begleitet sie dich – oder stört sie dich? Viele Entscheidungen waren daher nicht „mehr“, sondern Begleitung als Kern: auftauchen, wenn es passt, und ruhig bleiben, wenn das besser ist.","Uns ist eines wichtig: eine App zu bauen, die dich versteht, ohne über dich zu urteilen – und dir, wenn du sie brauchst, einen ruhigen, angenehmen Ort bietet, um Dampf abzulassen, zu erzählen und Gefühle festzuhalten."]},"features":{"title":"Features","items":{"emotion_card":{"title":"Emotionskarten","description":"Ziehe deine Emotionskarte und erkunde, was gerade in dir passiert.","icon":"🃏"},"ai_chat":{"title":"KI‑Chat","description":"Sprich jederzeit mit deinem Koala‑Begleiter und teile, was dich bewegt.","icon":"💬"},"venting_hole":{"title":"Baumloch","description":"Gib Unangenehmes und Geheimnisse sicher ins Baumloch – zum Loslassen.","icon":"🌳"},"diary":{"title":"Tagebuch","description":"Halte Momente und Gefühle fest und bewahre deine Erinnerungen.","icon":"✍️"},"ai_report":{"title":"KI‑Report","description":"Erhalte Einblicke aus deinen Einträgen, um dich besser zu verstehen.","icon":"📊"},"achievements":{"title":"Erfolge","description":"Schalte besondere Erfolge frei – durch Sammeln, Chatten und Schreiben.","icon":"🏆"}}},"users":{"title":"Für wen geeignet","tags":[{"title":"Gern Tagebuch schreiben","icon":"📒"},{"title":"Emotionales Wohlbefinden","icon":"❤️"},{"title":"Schneller Alltag","icon":"⚡"},{"title":"Stress abbauen","icon":"🍃"},{"title":"Wunsch nach Begleitung","icon":"🧸"},{"title":"Innere Ruhe","icon":"🧘"}]},"productIntro":{"mainTitle":"Kernfunktionen","sections":[{"title":"Plaudern & Reflektieren (KI-generiert)","items":["Sprich deine Gedanken in einem ruhigen, unterstützenden Raum durch","Sanfte Impulse helfen dir, deine Gefühle zu benennen und zu verstehen, warum sie wichtig sind"]},{"title":"Das Baumloch (privat entladen)","items":["Wirf deine Sorgen jederzeit in dein privates „Baumloch“","Ohne Bewertung – einfach ein Ort zum Loslassen und Weitergehen"]},{"title":"Stimmungs-Karten","items":["Ziehe Emotionskarten für schnelle Einsichten und Ermutigung","Kleine Erinnerungen, um umzufunktionieren und weiterzugehen"]},{"title":"Foto-Tagebuch","items":["Schreibe Tagebucheinträge und mache Fotos, wenn du den Moment festhalten willst","Oder lade ein Foto hoch, um Erinnerungen zusammenzuführen","Erstelle deine eigene Zeitlinie aus Gefühlen, Geschichten und Wachstum"]},{"title":"Wöchentliche Einblicke","items":["Einfache Zusammenfassungen basierend auf deinen In-App-Aktivitäten (z. B. Tagebuch/Tree Hole-Trends)","Hilft dir, Muster stressfrei zu entdecken"]}],"noteTitle":"Wichtiger Hinweis","noteBody":"Koala Haventree bietet unterstützende, KI-generierte Inhalte und Journaling-Tools. Es ist keine medizinische App und bietet keine Diagnose oder Behandlung. Wenn du in Gefahr bist oder über Selbstverletzung nachdenkst, kontaktiere sofort die örtlichen Rettungsdienste oder eine vertrauenswürdige Fachkraft."}},"footer":{"privacyPolicy":"Datenschutz","termsOfService":"Nutzungsbedingungen"}}'))},2101,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"Impulso Innovador","desc":"Integramos IA de vanguardia en cada proyecto creativo—rompemos límites y desbloqueamos posibilidades."},"design":{"title":"Estética de Diseño","desc":"Buscamos experiencias visuales excepcionales—cada píxel está cuidadosamente trabajado."},"quality":{"title":"Calidad Garantizada","desc":"Un sistema de calidad riguroso—cada entrega refleja nuestra búsqueda constante de excelencia."},"experience":{"title":"Experiencia al Centro","desc":"Del recorrido del usuario a los detalles de interacción—afinamos todo para que sea claro, fluido y fácil."},"maintenance":{"title":"Mantenimiento Continuo","desc":"El lanzamiento es solo el inicio—correcciones, mejoras e iteraciones para que la experiencia siga creciendo."},"security":{"title":"Seguridad y Privacidad","desc":"Proteger sus datos es nuestra máxima prioridad. Utilizamos medidas de seguridad líderes en la industria para garantizar que su información esté segura y sea confidencial."}},"feedbackButton":"Enviar comentarios","feedbackCardTitle":"Comparte tu opinión o inspiración","feedbackCardDesc":["Puedes escribirnos cuando quieras para reportar problemas o enviarnos ideas y sugerencias. Leemos cada mensaje y seguimos iterando para mejorar el producto. Cuéntanos qué te estorba y qué esperas; también qué te gustaría que agreguemos o mejoremos. Si puedes, incluye tu contexto de uso, capturas o pasos para reproducir: eso nos ayuda a localizar y mejorar más rápido.","Si te interesa colaborar creativamente o unirte al equipo, contáctanos cuando quieras."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"Genera rápidamente modelos 3D utilizables a partir de una sola imagen, previsualiza en tiempo real en el móvil y exporta a GLB/STL. No necesitas experiencia en 3D: lo que ves es lo que obtienes.","description":"Foto → Generar → Vista previa → Exportar. Todo en una sola pasada.","details":{"intro":"3D-PaiLiTi convierte una imagen en un modelo 3D utilizable, con vista previa en tiempo real en móvil y exportación a GLB/STL—sin experiencia 3D.","featureTitle":"Funciones clave","items":["Imagen→3D en un clic: importa una foto y genera un modelo 3D automáticamente (ideal como borrador editable).","Vista previa WYSIWYG: visor 3D integrado con rotación/zoom y presets de iluminación.","Múltiples formatos: exporta a GLB/STL para seguir editando en herramientas comunes.","Cola e historial: registra automáticamente las tareas para descargar y gestionar cuando quieras.","Caché sin conexión: los modelos generados se pueden ver offline.","Interfaz multilingüe: soporte para varios idiomas."]}},"koala":{"title":"Koala Haventree","subtitle":"Un espacio acogedor y privado para que tus emociones respiren.\\nChatea cuando necesites compañía, escribe cuando necesites claridad y usa herramientas suaves para soltar lo que se quedó dentro.","description":"Un lugar amable donde tus emociones pueden descansar.","details":{"sections":[{"title":"🗣️ Chat & Reflect (IA)","items":["Habla tus pensamientos en un espacio tranquilo y de apoyo","Sugerencias suaves para nombrar lo que sientes y por qué importa"]},{"title":"🕳️ The Tree Hole (Desahógate en privado)","items":["Deja tus preocupaciones en un “tree hole” privado cuando quieras","Sin juicio—solo un lugar para descargar y seguir adelante"]},{"title":"🎴 Mood Cards","items":["Saca cartas de emoción para una guía rápida y ánimo","Pequeños recordatorios para replantear y continuar"]},{"title":"📓 Diario con fotos","items":["Escribe entradas y toma una foto para capturar el momento","O sube una foto desde tu dispositivo para guardar recuerdos juntos","Crea tu propia línea del tiempo de emociones, historias y crecimiento"]},{"title":"📊 Insights semanales","items":["Resúmenes simples según tu actividad (p. ej., tendencias de diario/desahogo)","Útil para notar patrones—sin presión"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"Genera modelos 3D utilizables a partir de una sola imagen, previsualiza en tiempo real en móvil y exporta a GLB/STL. Sin experiencia 3D—verdadero WYSIWYG.","description":"3D-PaiLiTi es una aplicación innovadora que utiliza IA avanzada para transformar tus imágenes 2D en modelos 3D de alta calidad. Sube una foto y el algoritmo generará automáticamente un modelo detallado para previsualizar y exportar. Ideal para diseñadores, desarrolladores o entusiastas.","storyIntro":{"title":"3D-PaiLiTi — Historia","paragraphs":["Desde una chispa inicial hasta algo que realmente cobra vida en tu teléfono, el camino tuvo de todo: bloqueos, errores y pequeños momentos de alegría.","Para mí, es más que una app; es un viaje de aprendizaje para convertir ideas en realidad. Tal vez aún no sea perfecto, pero cada detalle lleva nuestro cuidado. Ojalá sientas esa dedicación y calidez."]},"features":{"title":"Funciones","items":{"ai_modeling":{"title":"Modelado con IA","description":"Convierte 2D a 3D en un clic con algoritmos avanzados.","icon":"🎨"},"export":{"title":"Exportación multi‑formato","description":"Soporta GLB, STL y otros formatos populares.","icon":"📦"},"preview":{"title":"Vista previa","description":"Vista 360° en tiempo real con entornos intercambiables.","icon":"👁️"},"optimization":{"title":"Optimización con IA","description":"Ajustes inteligentes y estilos para resultados más estables.","icon":"🔄"},"share":{"title":"Compartir","description":"Comparte tus resultados 3D fácilmente.","icon":"🌐"},"fast":{"title":"Generación rápida","description":"Proceso en la nube optimizado para obtener modelos útiles rápido.","icon":"⚡"}}},"users":{"title":"Para quién","tags":[{"title":"Desarrolladores de juegos","icon":"🎮"},{"title":"Creadores 3D","icon":"🧊"},{"title":"Arquitectos","icon":"🏛️"},{"title":"Diseño de producto","icon":"💡"},{"title":"Entusiastas del modelado","icon":"🧩"},{"title":"Creativos","icon":"🎨"},{"title":"Educación","icon":"🎓"}]},"productIntro":{"sectionTitle":"Funciones clave","items":["Conversión inmediata de imagen a 3D: importa una foto o imagen y genera automáticamente un modelo 3D para iterar y refinar con rapidez.","Vista previa WYSIWYG: el visor 3D incorporado permite rotar, hacer zoom y elegir varias luces ambientales.","Exportación en múltiples formatos: exporta a GLB/STL para seguir editando en motores y slicers populares.","Cola de tareas e historial: las tareas se guardan automáticamente para volver a descargarlas y administrarlas cuando necesites.","Caché offline: los modelos generados se pueden consultar sin conexión.","Interfaz multilingüe: admite chino, inglés, malayo, japonés, coreano y más idiomas."],"noteTitle":"Nota importante","noteBody":"Esta app se enfoca en generar rápidamente con un clic modelos base editables. La automatización puede no alcanzar el nivel de detalle artesanal; para mayor precisión y mejor topología, continúa puliendo en tu software 3D favorito."}},"koalaPage":{"title":"Koala Haventree","subtitle":"Un lugar amable donde tus emociones pueden descansar.","description":"Koala Haventree es un juego móvil único que ofrece un espacio tranquilo y reconfortante para relajarte y reflexionar. En este mundo en paz, puedes cultivar “árboles emocionales”, interactuar con criaturas del bosque y crear tu propio refugio. Su estilo calmante te ayuda a encontrar momentos de serenidad.","storyIntro":{"title":"Koala Haventree — Historia","paragraphs":["Esta vez intentamos por primera vez pulir una app de IA con sensibilidad emocional. Lo más difícil no fue hacerla “más habladora”, sino enseñarle límites: que sea más humana, más considerada, capaz de sostener tus emociones y de darte un espacio seguro para abrirte.","Puedes cambiar de rol según lo necesites, para que te hable con un tono más humano: puede bromear contigo y también saber medir la distancia — estar presente cuando hace falta una palabra más, y acompañar en silencio cuando no conviene interrumpir. A menudo nos preguntamos: ¿te acompaña o te molesta? Muchas decisiones no fueron para hacer “más”, sino para poner el acompañamiento en el centro: aparecer cuando debe, y callar cuando es mejor.","Queremos cuidar una cosa: crear una app que te entienda sin sacar conclusiones por ti; y que, cuando lo necesites, te ofrezca un lugar tranquilo y cómodo para desahogarte, hablar y registrar cómo te sientes."]},"features":{"title":"Funciones","items":{"emotion_card":{"title":"Cartas de emoción","description":"Saca tu carta para explorar cómo te sientes.","icon":"🃏"},"ai_chat":{"title":"Chat con IA","description":"Habla cuando quieras con tu compañero koala.","icon":"💬"},"venting_hole":{"title":"Tree hole","description":"Confía tus preocupaciones en privado para liberar tensión.","icon":"🌳"},"diary":{"title":"Diario","description":"Registra momentos y estados de ánimo para guardar tus recuerdos.","icon":"✍️"},"ai_report":{"title":"Informe con IA","description":"Resúmenes a partir de tus entradas para entenderte mejor.","icon":"📊"},"achievements":{"title":"Logros","description":"Desbloquea logros únicos al coleccionar, chatear y registrar.","icon":"🏆"}}},"users":{"title":"Para quién","tags":[{"title":"Te gusta escribir","icon":"📒"},{"title":"Bienestar emocional","icon":"❤️"},{"title":"Vida acelerada","icon":"⚡"},{"title":"Aliviar estrés","icon":"🍃"},{"title":"Buscas compañía","icon":"🧸"},{"title":"Paz interior","icon":"🧘"}]},"productIntro":{"mainTitle":"Funciones principales","sections":[{"title":"Charla y reflexión (IA)","items":["Habla sobre tus pensamientos en un espacio tranquilo y de apoyo","Recibe sugerencias suaves para nombrar lo que sientes y por qué importa"]},{"title":"El agujero del árbol (Desahógate en privado)","items":["Deja tus preocupaciones en un “tree hole” privado cuando quieras","Sin juicios—solo un lugar para descargar y seguir adelante"]},{"title":"Cartas de estado de ánimo","items":["Extrae cartas de emoción para obtener rápido insight y ánimo","Pequeños recordatorios que ayudan a replantear y continuar"]},{"title":"Diario fotográfico","items":["Escribe entradas de diario y toma una foto cuando quieras capturar el momento","O sube una foto para mantener tus recuerdos juntos","Construye tu propia línea de tiempo de emociones, historias y crecimiento"]},{"title":"Perspectivas semanales","items":["Resúmenes simples basados en tu actividad en la app (p.ej., diario/venting)","Te ayudan a notar patrones sin presión"]}],"noteTitle":"Nota importante","noteBody":"Koala Haventree ofrece contenido y herramientas de diario generadas por IA. No es una app médica ni brinda diagnóstico o tratamiento. Si estás en peligro o considerando autolesionarte, contacta de inmediato a los servicios de emergencia locales o a un profesional confiable."}},"footer":{"privacyPolicy":"Política de privacidad","termsOfService":"Términos del servicio"}}'))},62914,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"Innovation","desc":"Nous intégrons l’IA de pointe à chaque projet créatif — pour dépasser les limites et ouvrir de nouvelles possibilités."},"design":{"title":"Esthétique","desc":"Nous visons une expérience visuelle d’exception — chaque pixel est travaillé avec soin."},"quality":{"title":"Qualité","desc":"Un contrôle qualité rigoureux — chaque livrable reflète notre exigence d’excellence."},"experience":{"title":"Expérience au cœur","desc":"Du parcours utilisateur aux micro‑interactions, nous peaufinons jusqu’à obtenir une utilisation claire et fluide."},"maintenance":{"title":"Maintenance continue","desc":"Après la mise en ligne : correctifs, optimisations et itérations — pour une amélioration durable."},"security":{"title":"Sécurité et Confidentialité","desc":"La protection de vos données est notre priorité absolue. Nous utilisons des mesures de sécurité de pointe pour garantir la sécurité et la confidentialité de vos informations."}},"feedbackButton":"Envoyer un retour","feedbackCardTitle":"Partagez vos remarques ou inspirations","feedbackCardDesc":["N’hésitez pas à nous signaler un problème ou à nous envoyer vos idées et suggestions. Nous lisons chaque retour et itérons en continu pour améliorer le produit. Partagez ce qui vous bloque, ce que vous attendez, ou ce que vous aimeriez voir ajouté ou amélioré. Des captures d’écran, le contexte d’usage ou des étapes de reproduction nous aident à corriger plus vite.","Si vous souhaitez une collaboration créative ou rejoindre l’équipe, contactez‑nous quand vous voulez."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"Générez rapidement des modèles 3D utilisables à partir d’une seule image, prévisualisez en temps réel sur mobile et exportez en GLB/STL. Pas besoin de bases en 3D : ce que vous voyez est ce que vous obtenez.","description":"Photo → Génération → Aperçu → Export. Tout-en-un.","details":{"intro":"3D-PaiLiTi transforme une image en modèle 3D utilisable, avec aperçu en temps réel sur mobile et export GLB/STL — sans expérience 3D.","featureTitle":"Fonctionnalités clés","items":["Image → 3D en un clic : importez une photo pour générer automatiquement un modèle 3D (idéal comme brouillon éditable).","Aperçu WYSIWYG : visionneuse 3D intégrée (rotation/zoom) et presets d’éclairage.","Exports multiples : exportez en GLB/STL pour poursuivre dans vos outils.","File d’attente & historique : les tâches sont enregistrées automatiquement.","Cache hors ligne : les modèles générés restent consultables hors connexion.","Interface multilingue : plusieurs langues prises en charge."]}},"koala":{"title":"Koala Haventree","subtitle":"Un espace cosy et privé pour laisser vos émotions respirer.\\nDiscutez quand vous avez besoin de compagnie, écrivez quand vous cherchez de la clarté, et utilisez des outils doux pour relâcher ce qui reste bloqué.","description":"Un lieu doux où vos émotions peuvent se poser.","details":{"sections":[{"title":"🗣️ Chat & Reflect (IA)","items":["Exprimez vos pensées dans un espace calme et bienveillant","Des invites douces pour nommer ce que vous ressentez et pourquoi cela compte"]},{"title":"🕳️ Le trou d’arbre (confier en privé)","items":["Déposez vos soucis dans un « trou d’arbre » privé, à tout moment","Sans jugement — juste un endroit pour se décharger et avancer"]},{"title":"🎴 Cartes d’humeur","items":["Tirez des cartes d’émotions pour un éclairage rapide et du réconfort","De petits rappels pour recadrer et continuer"]},{"title":"📓 Journal photo","items":["Écrivez une entrée et prenez une photo quand vous voulez capturer l’instant","Ou importez une photo de votre appareil pour rassembler vos souvenirs","Construisez votre propre timeline d’émotions, d’histoires et de progrès"]},{"title":"📊 Bilans hebdomadaires","items":["Résumés simples basés sur votre activité (ex. tendances journal/venting)","Utile pour repérer des schémas — sans pression"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"Générez des modèles 3D utilisables à partir d’une seule image, prévisualisez-les en temps réel sur mobile et exportez-les en GLB/STL. Pas besoin d’expérience 3D — un vrai WYSIWYG.","description":"3D-PaiLiTi est une application innovante qui utilise une IA avancée pour transformer vos images 2D en modèles 3D de haute qualité. Importez une photo : l’algorithme génère automatiquement un modèle détaillé, prévisualisable en temps réel et exportable. Que vous soyez designer, développeur ou passionné, 3D-PaiLiTi simplifie votre workflow et ouvre de nouvelles dimensions.","storyIntro":{"title":"3D-PaiLiTi — Récit","paragraphs":["D’une première étincelle d’idée à quelque chose qui s’anime vraiment sur ton téléphone, le chemin a été riche en détours — blocages, erreurs, et petits moments de joie.","Pour moi, ce n’est pas seulement une app ; c’est un apprentissage pour transformer une idée en réalité. Ce n’est peut‑être pas parfait, mais chaque détail porte notre soin. J’espère que tu ressentiras cette sincérité et cette chaleur."]},"features":{"title":"Fonctionnalités","items":{"ai_modeling":{"title":"Modélisation IA","description":"Conversion 2D→3D en un clic grâce à des algorithmes avancés.","icon":"🎨"},"export":{"title":"Export multi‑formats","description":"Exportez en GLB, STL et autres formats populaires.","icon":"📦"},"preview":{"title":"Aperçu en ligne","description":"Vue 360° en temps réel avec environnements au choix.","icon":"👁️"},"optimization":{"title":"Optimisation IA","description":"Ajustements intelligents et stylisation pour des résultats plus stables.","icon":"🔄"},"share":{"title":"Partage","description":"Partagez facilement vos créations 3D.","icon":"🌐"},"fast":{"title":"Génération rapide","description":"Process cloud optimisé pour des modèles utilisables rapidement.","icon":"⚡"}}},"users":{"title":"Pour qui ?","tags":[{"title":"Créateurs de jeux","icon":"🎮"},{"title":"Artistes 3D","icon":"🧊"},{"title":"Architectes","icon":"🏛️"},{"title":"Design produit","icon":"💡"},{"title":"Passionnés de modèles","icon":"🧩"},{"title":"Créatifs","icon":"🎨"},{"title":"Éducation","icon":"🎓"}]},"productIntro":{"sectionTitle":"Fonctions principales","items":["Conversion image-vers-3D en un clic : importez une photo ou image et générez automatiquement un modèle 3D pour itérer et affiner rapidement.","Aperçu WYSIWYG : le visualiseur 3D intégré permet de faire pivoter, zoomer et tester plusieurs ambiances lumineuses.","Export multi-formats : exportez en GLB/STL pour continuer l\'édition dans vos moteurs et trancheurs favoris.","File d\'attente et historique : les tâches sont enregistrées automatiquement pour les retélécharger et gérer à tout moment.","Cache hors ligne : les modèles générés restent consultables même sans connexion.","Interface multilingue : prend en charge le chinois, l\'anglais, le malais, le japonais, le coréen et d\'autres langues."],"noteTitle":"Note importante","noteBody":"Cette application privilégie la génération rapide d’un modèle de base éditable en un clic. L’automatisation ne garantit pas toujours la même finesse qu’un travail manuel ; pour plus de précision et une meilleure topologie, poursuivez le polissage dans votre logiciel 3D préféré."}},"koalaPage":{"title":"Koala Haventree","subtitle":"Un lieu doux où vos émotions peuvent se poser.","description":"Koala Haventree est un jeu mobile unique qui offre un espace paisible et réconfortant pour se détendre et se recentrer. Dans ce monde tranquille, vous pouvez faire grandir vos « arbres d’émotions », interagir avec des créatures bienveillantes et créer un refuge personnalisé. Avec son style apaisant, Koala Haventree vous aide à retrouver des instants de calme au quotidien.","storyIntro":{"title":"Koala Haventree — Récit","paragraphs":["Cette fois, nous essayons pour la première fois de peaufiner une application IA « avec émotion ». Le plus difficile n’a pas été de la rendre « plus bavarde », mais de lui apprendre la mesure : plus humaine, plus respectueuse, capable d’accueillir tes émotions et de te laisser te confier en sécurité.","Tu peux changer de rôle selon tes besoins, pour qu’elle te parle avec un ton plus proche d’une vraie personne — elle peut plaisanter, mais sait aussi garder la bonne distance : présente quand un mot de plus est nécessaire, et discrète quand le silence accompagne mieux. On s’arrête souvent pour se demander : est‑ce qu’elle t’accompagne, ou est‑ce qu’elle te dérange ? Beaucoup de choix ne visaient pas à faire « plus », mais à mettre l’accompagnement au centre : apparaître quand il faut, rester tranquille quand c’est mieux.","Nous voulons garder une chose : créer une app qui te comprend sans te juger — et qui, quand tu en as besoin, t’offre un endroit calme et confortable pour te défouler, te confier, et noter tes humeurs."]},"features":{"title":"Fonctionnalités","items":{"emotion_card":{"title":"Cartes d’émotions","description":"Tirez votre carte pour explorer ce que vous ressentez.","icon":"🃏"},"ai_chat":{"title":"Chat IA","description":"Discutez à tout moment avec votre compagnon koala.","icon":"💬"},"venting_hole":{"title":"Trou d’arbre","description":"Confiez vos secrets et vos tracas — pour relâcher la pression.","icon":"🌳"},"diary":{"title":"Journal","description":"Notez vos moments et vos humeurs pour garder vos souvenirs.","icon":"✍️"},"ai_report":{"title":"Rapport IA","description":"Des synthèses basées sur vos notes pour mieux vous comprendre.","icon":"📊"},"achievements":{"title":"Succès","description":"Débloquez des succès en collectionnant, discutant et écrivant.","icon":"🏆"}}},"users":{"title":"Public concerné","tags":[{"title":"Aime écrire","icon":"📒"},{"title":"Bien‑être émotionnel","icon":"❤️"},{"title":"Rythme soutenu","icon":"⚡"},{"title":"Réduire le stress","icon":"🍃"},{"title":"Besoin de compagnie","icon":"🧸"},{"title":"Cherche la sérénité","icon":"🧘"}]},"productIntro":{"mainTitle":"Fonctions principales","sections":[{"title":"Discuter & Réfléchir (IA générée)","items":["Parle de tes pensées dans un espace calme et bienveillant","Des suggestions douces pour nommer ce que tu ressens et pourquoi c’est important"]},{"title":"Le trou d’arbre (décharge privée)","items":["Dépose tes soucis dans un « tree hole » privé quand tu veux","Sans jugement, juste un lieu pour libérer et continuer"]},{"title":"Cartes d’humeur","items":["Tire des cartes d’émotions pour un aperçu rapide et de l’encouragement","De petits rappels pour changer de perspective et avancer"]},{"title":"Journal photo","items":["Écris des entrées et prends une photo quand tu veux capturer l’instant","Ou téléverse une photo pour garder tes souvenirs ensemble","Construis ta propre timeline d’émotions, d’histoires et de croissance"]},{"title":"Aperçus hebdomadaires","items":["Des résumés simples basés sur ton activité dans l’appli (ex : journaling, tree hole)","Ils t’aident à repérer des patterns sans pression"]}],"noteTitle":"Note importante","noteBody":"Koala Haventree propose des contenus et outils de journalisation soutenus par l’IA, mais ce n’est pas une application médicale et elle ne fournit ni diagnostic ni traitement. Si tu es en danger ou envisages de te faire du mal, contacte immédiatement les services d’urgence locaux ou un professionnel de confiance."}},"footer":{"privacyPolicy":"Politique de confidentialité","termsOfService":"Conditions d’utilisation"}}'))},20890,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"नवाचार","desc":"हर रचनात्मक प्रोजेक्ट में अत्याधुनिक AI जोड़कर हम सीमाएँ तोड़ते हैं और नई संभावनाएँ खोलते हैं।"},"design":{"title":"डिज़ाइन सौंदर्य","desc":"बेहतरीन विज़ुअल अनुभव—हर पिक्सेल को सावधानी से तराशा जाता है।"},"quality":{"title":"गुणवत्ता","desc":"कड़ा क्वालिटी सिस्टम—हर डिलिवरेबल हमारी उत्कृष्टता की प्रतिबद्धता दर्शाता है।"},"experience":{"title":"अनुभव‑केंद्रित","desc":"यूज़र जर्नी से लेकर इंटरैक्शन डिटेल तक—सब कुछ स्पष्ट, सहज और स्मूद बनाने के लिए निरंतर सुधार।"},"maintenance":{"title":"लगातार मेंटेनेंस","desc":"लॉन्च के बाद भी—फिक्स, ऑप्टिमाइज़ेशन और इटरेशन के साथ अनुभव को बेहतर बनाते रहते हैं।"},"security":{"title":"सुरक्षा और गोपनीयता","desc":"आपके डेटा की सुरक्षा हमारी सर्वोच्च प्राथमिकता है। हम यह सुनिश्चित करने के लिए उद्योग-अग्रणी सुरक्षा उपायों का उपयोग करते हैं कि आपकी जानकारी सुरक्षित और गोपनीय है।"}},"feedbackButton":"फीडबैक भेजें","feedbackCardTitle":"अपनी प्रतिक्रिया या प्रेरणा साझा करें","feedbackCardDesc":["आप कभी भी समस्याएँ बता सकते हैं या अपने विचार और सुझाव भेज सकते हैं। हम हर फीडबैक ध्यान से पढ़ते हैं और लगातार सुधार करते रहते हैं ताकि उत्पाद और बेहतर हो। इस्तेमाल के दौरान क्या अटक रहा था, आपकी क्या अपेक्षाएँ हैं, या भविष्य में आप क्या जोड़/सुधार देखना चाहते हैं—ज़रूर बताइए। यदि संभव हो, तो उपयोग‑परिस्थिति, स्क्रीनशॉट या पुनरुत्पादन चरण भी साझा करें—इससे हमें जल्दी पहचानने और सुधार करने में मदद मिलेगी।","यदि आप क्रिएटिव सहयोग करना चाहते हैं या टीम में शामिल होने में रुचि रखते हैं, तो कभी भी हमसे संपर्क करें।"]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"एक ही तस्वीर से उपयोगी 3D मॉडल तेज़ी से बनाएं, मोबाइल पर रियल‑टाइम प्रीव्यू देखें और GLB/STL में आसानी से एक्सपोर्ट करें। 3D की कोई समझ ज़रूरी नहीं—जो दिखे वही मिले।","description":"फोटो → जनरेट → प्रीव्यू → एक्सपोर्ट — सब कुछ एक बार में.","details":{"intro":"3D-PaiLiTi एक इमेज को उपयोगी 3D मॉडल में बदलता है, मोबाइल पर रियल‑टाइम प्रिव्यू देता है और GLB/STL में एक्सपोर्ट करता है—बिना 3D अनुभव के।","featureTitle":"मुख्य फीचर्स","items":["वन‑क्लिक इमेज‑टू‑3D: फोटो/इमेज इम्पोर्ट करें और ऑटो 3D मॉडल बनाएं (एडिटेबल ड्राफ्ट के लिए बढ़िया)।","WYSIWYG प्रिव्यू: बिल्ट‑इन 3D व्यूअर—रोटेट/ज़ूम और कई लाइटिंग प्रीसेट।","मल्टी‑फॉर्मेट एक्सपोर्ट: GLB/STL में एक्सपोर्ट करके आगे टूल्स में एडिट करें।","टास्क क्यू & हिस्ट्री: जॉब्स ऑटो रिकॉर्ड—कभी भी डाउनलोड/मैनेज।","ऑफलाइन कैश: जनरेटेड मॉडल ऑफलाइन भी देखे जा सकते हैं।","मल्टीलिंगुअल UI: कई भाषाओं का सपोर्ट।"]}},"koala":{"title":"Koala Haventree","subtitle":"एक आरामदायक, निजी जगह जहाँ आपकी भावनाएँ खुलकर साँस ले सकें।\\nजब साथ चाहिए तो चैट करें, जब स्पष्टता चाहिए तो लिखें, और जो अंदर अटका है उसे धीरे‑धीरे छोड़ने के लिए नरम टूल्स इस्तेमाल करें।","description":"भावनाओं के लिए एक सौम्य ठिकाना।","details":{"sections":[{"title":"🗣️ Chat & Reflect (AI‑generated)","items":["शांत, सहायक माहौल में अपने विचार साझा करें","नरम संकेत जो आपको यह नाम देने में मदद करें कि आप क्या महसूस कर रहे हैं और क्यों"]},{"title":"🕳️ The Tree Hole (Private vent)","items":["कभी भी अपनी चिंता एक निजी “ट्री होल” में छोड़ दें","बिना जजमेंट—बस हल्का होने और आगे बढ़ने की जगह"]},{"title":"🎴 Mood Cards","items":["त्वरित समझ और प्रोत्साहन के लिए इमोशन कार्ड्स निकालें","छोटे‑छोटे रिमाइंडर्स जो दृष्टिकोण बदलने में मदद करें"]},{"title":"📓 Photo Journal","items":["जब चाहें डायरी लिखें और पल कैद करने के लिए फोटो लें","या डिवाइस से फोटो अपलोड करके यादों को साथ रखें","भावनाओं, कहानियों और ग्रोथ की अपनी टाइमलाइन बनाएं"]},{"title":"📊 Weekly Insights","items":["ऐप गतिविधि के आधार पर सरल सारांश (जैसे जर्नल/वेंटिंग ट्रेंड्स)","पैटर्न समझने में मदद—बिना दबाव"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"एक इमेज को उपयोगी 3D मॉडल में बदलता है, मोबाइल पर रियल‑टाइम प्रिव्यू देता है और GLB/STL में एक्सपोर्ट करता है—बिना 3D अनुभव के।","description":"3D-PaiLiTi एक नवोन्मेषी ऐप है जो उन्नत AI की मदद से आपकी 2D इमेज को उच्च‑गुणवत्ता वाले 3D मॉडल में बदलता है। बस फोटो अपलोड करें—एल्गोरिद्म एक डिटेल्ड 3D मॉडल बनाता है जिसे आप रियल‑टाइम में देख और एक्सपोर्ट कर सकते हैं। डिजाइनर, डेवलपर या हॉबीस्ट—सबके लिए यह वर्कफ़्लो को सरल बनाता है।","storyIntro":{"title":"3D-PaiLiTi — कहानी","paragraphs":["पहले विचार की चिंगारी से लेकर फोन पर सच में “चलने” तक, यह सफर आसान नहीं था—रुकावटें, गलतियाँ और छोटी‑छोटी खुशियाँ भी रहीं।","मेरे लिए यह सिर्फ एक ऐप नहीं, बल्कि “विचार को हकीकत में बदलने” की सीखने वाली यात्रा है। शायद अभी परफेक्ट नहीं, लेकिन हर डिटेल में हमारा ध्यान और मेहनत है। उम्मीद है आपको वह ईमानदारी और गर्माहट महसूस होगी।"]},"features":{"title":"फ़ीचर्स","items":{"ai_modeling":{"title":"AI मॉडलिंग","description":"एक क्लिक में 2D इमेज को 3D मॉडल में बदलें।","icon":"🎨"},"export":{"title":"एक्सपोर्ट","description":"GLB, STL जैसे लोकप्रिय 3D फ़ॉर्मेट्स सपोर्ट।","icon":"📦"},"preview":{"title":"लाइव प्रिव्यू","description":"रियल‑टाइम 360° व्यू और अलग‑अलग एनवायरनमेंट।","icon":"👁️"},"optimization":{"title":"AI ऑप्टिमाइज़ेशन","description":"स्थिर परिणामों के लिए इंटेलिजेंट एडजस्टमेंट/स्टाइल।","icon":"🔄"},"share":{"title":"शेयर","description":"3D परिणाम टीम या सोशल पर आसानी से साझा करें।","icon":"🌐"},"fast":{"title":"तेज़ जनरेशन","description":"ऑप्टिमाइज़्ड क्लाउड प्रोसेस से जल्दी उपयोगी मॉडल।","icon":"⚡"}}},"users":{"title":"किनके लिए","tags":[{"title":"गेम डेवलपर्स","icon":"🎮"},{"title":"3D क्रिएटर्स","icon":"🧊"},{"title":"आर्किटेक्ट्स","icon":"🏛️"},{"title":"प्रोडक्ट डिज़ाइनर्स","icon":"💡"},{"title":"मॉडलिंग शौकीन","icon":"🧩"},{"title":"क्रिएटिव प्रोफेशनल्स","icon":"🎨"},{"title":"शिक्षक","icon":"🎓"}]},"productIntro":{"sectionTitle":"मुख्य विशेषताएँ","items":["एक क्लिक में इमेज से 3D: फोटो या छवि आयात करें और स्वतः 3D मॉडल बनाकर तेजी से संपादन करें।","WYSIWYG पूर्वावलोकन: इन-बिल्ट 3D व्यूअर घुमाना, ज़ूम और कई लाइटिंग प्रीसेट्स देता है।","कई निर्यात फ़ॉर्मेट: GLB/STL में निर्यात करके लोकप्रिय इंजनों व स्लीसरों में आगे संपादित करें।","टास्क कतार व इतिहास: पूरी रिकार्ड ऑटोमैटिकली सेव होता है ताकि आप कभी भी फिर डाउनलोड और मैनेज कर सकें।","ऑफ़लाइन कैश: बनाए मॉडल नेटवर्क के बिना भी देखें।","बहुभाषी UI: चीनी, अंग्रेज़ी, मलय, जापानी, कोरियाई और अन्य भाषाएँ समर्थित हैं।"],"noteTitle":"महत्वपूर्ण सूचना","noteBody":"यह ऐप एक क्लिक में संपादनीय बेस मॉडल बनाने पर केंद्रित है। ऑटोमेशन हमेशा हाथ से बने विवरण जैसी सूक्ष्मता नहीं देता; उच्च सटीकता और बेहतर टोपोलॉजी के लिए अपने पसंदीदा 3D संपादन सॉफ़्टवेयर में आगे ब्रश करें।"}},"koalaPage":{"title":"Koala Haventree","subtitle":"भावनाओं के लिए एक सौम्य ठिकाना।","description":"Koala Haventree एक अनोखा मोबाइल गेम है जो आराम और आत्म‑चिंतन के लिए शांत, सुकूनभरा स्पेस देता है। इस शांत दुनिया में आप अपने “इमोशन ट्री” उगा सकते हैं, नरम‑दिल जंगल के जीवों के साथ बातचीत कर सकते हैं, और अपना निजी आश्रय बना सकते हैं। इसका सुकूनभरा आर्ट‑स्टाइल आपको रोज़मर्रा की भागदौड़ से थोड़ी राहत देता है।","storyIntro":{"title":"Koala Haventree — कहानी","paragraphs":["इस बार हम पहली बार एक भावनात्मक रूप से संवेदनशील AI ऐप को निखारने की कोशिश कर रहे हैं। सबसे ज़्यादा मेहनत “इसे ज़्यादा बोलने वाला” बनाने में नहीं, बल्कि इसे सीमाएँ समझाने में लगी—ताकि यह ज़्यादा मानवीय हो, ज़्यादा समझदार हो, आपकी भावनाओं को थाम सके और आपको सुरक्षित महसूस करा सके।","आप ज़रूरत के हिसाब से अलग‑अलग रोल चुन सकते हैं, ताकि यह किसी इंसान की तरह बात करे—मज़ाक भी करे और साथ ही मर्यादा भी रखे: जब एक वाक्य ज़्यादा कहना चाहिए तब मौजूद रहे, और जब चुपचाप साथ होना बेहतर हो तब बाधा न बने। हम अक्सर खुद से पूछते हैं: यह आपका साथ दे रहा है या आपको परेशान कर रहा है? इसलिए कई फैसले “और ज़्यादा करने” के लिए नहीं, बल्कि साथ देने को केंद्र में रखकर लिए गए: ज़रूरत पर सामने आए, और ज़रूरत पर शांत रहे।","हम एक बात बचाए रखना चाहते हैं: एक ऐसा ऐप जो आपको समझे, पर आपके लिए निष्कर्ष न निकाले—और जब आपको ज़रूरत हो, आपको एक शांत, आरामदायक जगह दे जहाँ आप खुलकर कह सकें, मन हल्का कर सकें और अपनी भावनाएँ दर्ज कर सकें।"]},"features":{"title":"फ़ीचर्स","items":{"emotion_card":{"title":"इमोशन कार्ड्स","description":"अपना इमोशन कार्ड निकालें और मन की हलचल समझें।","icon":"🃏"},"ai_chat":{"title":"AI चैट","description":"कभी भी अपने प्यारे कोआला साथी से बात करें।","icon":"💬"},"venting_hole":{"title":"ट्री होल","description":"अपनी बातें सुरक्षित रूप से ‘ट्री होल’ को सौंपें।","icon":"🌳"},"diary":{"title":"डायरी","description":"दिन‑प्रतिदिन के पल और भावनाएँ लिखकर संजोएँ।","icon":"✍️"},"ai_report":{"title":"AI रिपोर्ट","description":"आपकी नोट्स से सरल इनसाइट्स, खुद को बेहतर समझने के लिए।","icon":"📊"},"achievements":{"title":"अचीवमेंट्स","description":"कलेक्शन, चैट और रिकॉर्डिंग से खास उपलब्धियाँ अनलॉक करें।","icon":"🏆"}}},"users":{"title":"किनके लिए","tags":[{"title":"लिखना पसंद","icon":"📒"},{"title":"इमोशनल वेलनेस","icon":"❤️"},{"title":"तेज़ जीवन‑शैली","icon":"⚡"},{"title":"तनाव कम करना","icon":"🍃"},{"title":"साथ की चाह","icon":"🧸"},{"title":"आंतरिक शांति","icon":"🧘"}]},"productIntro":{"mainTitle":"मुख्य फीचर्स","sections":[{"title":"चैट और चिंतन (एआई)","items":["शांत और सहायक स्पेस में अपने विचारों को व्यक्त करें","नरम संकेत मदद करते हैं कि आप क्या महसूस कर रहे हैं और क्यों वह महत्वपूर्ण है"]},{"title":"ट्री होल (निजी रूप से साझा)","items":["किसी भी समय अपनी चिंताओं को निजी “ट्री होल” में डालें","कोई निर्णय नहीं – बस एक जगह जहां आप हल्का हो सकते हैं और आगे बढ़ सकते हैं"]},{"title":"मूड कार्ड्स","items":["त्वरित अंतर्दृष्टि और प्रोत्साहन के लिए इमोशन कार्ड्स निकालें","छोटे याद दिलाने आपको नया दृष्टिकोण अपनाने और आगे बढ़ने में मदद करते हैं"]},{"title":"फोटो जर्नल","items":["डायरी लिखें और एक फोटो लें जब आप पल को कैप्चर करना चाहें","या अपने डिवाइस से फोटो अपलोड करें और यादों को एक साथ रखें","अपनी भावनाओं, कहानियों और विकास की खुद की टाइमलाइन बनाएं"]},{"title":"साप्ताहिक इनसाइट्स","items":["इन-एप गतिविधियों (जैसे डायरी/Tree Hole ट्रेंड) पर आधारित सरल सार","बिना दबाव के पैटर्न पहचानने में मदद करता है"]}],"noteTitle":"महत्वपूर्ण सूचना","noteBody":"Koala Haventree सहायक, AI जनित कंटेंट और जर्नलिंग टूल्स देता है। यह कोई मेडिकल ऐप नहीं है और न ही उपचार/निदान प्रदान करता है। यदि आप ख़तरे में हैं या आत्म-क्षति के बारे में सोच रहे हैं, तो तुरंत स्थानीय आपातकालीन सेवाओं या किसी भरोसेमंद प्रोफेशनल से संपर्क करें।"}},"footer":{"privacyPolicy":"गोपनीयता नीति","termsOfService":"सेवा की शर्तें"}}'))},35115,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"イノベーション","desc":"最先端のAIをすべてのクリエイティブに。常識を超えて新しい可能性を広げます。"},"design":{"title":"デザイン美学","desc":"視覚体験を徹底追求。細部まで丁寧に磨き上げます。"},"quality":{"title":"品質保証","desc":"厳格な品質基準。成果物すべてに妥協しません。"},"experience":{"title":"体験中心","desc":"ユーザー導線から操作感まで。分かりやすく、滑らかで、使いやすく仕上げます。"},"maintenance":{"title":"継続運用","desc":"公開後も改善を継続。修正・最適化・反復で体験を伸ばします。"},"security":{"title":"セキュリティとプライバシー","desc":"お客様のデータを保護することは、私たちの最優先事項です。業界をリードするセキュリティ対策を用いて、お客様の情報が安全かつ機密に保たれることを保証します。"}},"feedbackButton":"フィードバックを送る","feedbackCardTitle":"ご意見・ひらめきを共有","feedbackCardDesc":["いつでも不具合の報告や、アイデア・ご提案をお寄せください。いただいた内容は一つひとつ丁寧に読み、継続的に改善を重ねて、より良いプロダクトにしていきます。使っていて困った点や期待していること、今後追加・改善してほしい方向性など、ぜひ教えてください。可能であれば、利用シーン、スクリーンショット、再現手順も添えていただけると、原因特定と改善が早くなります。","クリエイティブな協業やチーム参加にご関心がある方も、いつでもお気軽にご連絡ください。"]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"1枚の画像から使える3Dモデルを素早く生成し、スマホでリアルタイムにプレビュー、GLB/STLで簡単に書き出せます。3Dの知識は不要、見たままがそのまま。","description":"撮影→生成→プレビュー→書き出し、これ一つで完了。","details":{"intro":"3D-PaiLiTi は1枚の画像から使える3Dモデルを生成し、モバイルでリアルタイムに確認してGLB/STLへエクスポートできます。3Dの知識は不要です。","featureTitle":"主な機能","items":["画像→3Dをワンクリック：写真を取り込むだけで自動生成（編集用の下書きに最適）。","WYSIWYGプレビュー：回転/ズーム対応の3Dビューアと複数のライティングプリセット。","複数形式のエクスポート：GLB/STLで一般的なツールへ引き継ぎ。","キュー＆履歴：生成タスクを自動で記録し、いつでも管理/再ダウンロード。","オフラインキャッシュ：生成したモデルはオフラインでも閲覧可能。","多言語UI：複数言語に対応。"]}},"koala":{"title":"Koala Haventree","subtitle":"気持ちが息をできる、居心地のよいプライベート空間。\\n誰かが欲しいときはチャット、整理したいときは書く。優しいツールで心の中の“つかえ”をほどきます。","description":"気持ちがそっと着地できる場所。","details":{"sections":[{"title":"🗣️ Chat & Reflect（AI生成）","items":["落ち着いたサポート空間で、考えを言葉にできます","優しいプロンプトで「何を感じているか」「なぜ大切か」を整理"]},{"title":"🕳️ Tree Hole（こっそり吐き出す）","items":["不安をいつでもプライベートな“木の穴”へ","ジャッジなし。吐き出して前に進むための場所"]},{"title":"🎴 Mood Cards","items":["感情カードで小さなヒントと励ましを","捉え直しを助ける、ささやかなリマインダー"]},{"title":"📓 フォト日記","items":["記録したいときに日記を書き、写真で瞬間を残す","端末から写真をアップロードして思い出をまとめる","感情・物語・成長のタイムラインを作れます"]},{"title":"📊 週間インサイト","items":["アプリ内行動に基づく簡単なサマリー（例：日記/吐き出しの傾向）","プレッシャーなくパターンに気づけます"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"1枚の画像から使える3Dモデルを生成し、モバイルでリアルタイムに確認してGLB/STLへエクスポートできます。3Dの知識は不要です。","description":"3D-PaiLiTi は先進的なAIで2D画像を高品質な3Dモデルへ変換します。写真をアップロードするだけで、詳細なモデルを自動生成し、リアルタイムに確認・エクスポートできます。デザイナー、開発者、趣味の方まで、制作をスムーズにします。","storyIntro":{"title":"3D-PaiLiTi — ストーリー","paragraphs":["最初のひらめきが、スマホの中で本当に動き出すものになるまで――道のりは決して平坦ではありませんでした。行き詰まりも、失敗も、そして小さな喜びもありました。","私にとってこれは単なるアプリではなく、「アイデアを現実にする」学びの旅です。まだ完璧ではないかもしれませんが、細部の一つひとつに私たちの想いが詰まっています。その真剣さと温度が、あなたにも伝われば嬉しいです。"]},"features":{"title":"機能","items":{"ai_modeling":{"title":"AIモデリング","description":"2D画像をワンクリックで3Dへ変換。","icon":"🎨"},"export":{"title":"多形式エクスポート","description":"GLB/STLなど主要形式に対応。","icon":"📦"},"preview":{"title":"プレビュー","description":"360°リアルタイム表示。環境も切替可能。","icon":"👁️"},"optimization":{"title":"AI最適化","description":"安定した結果のための調整・スタイル化。","icon":"🔄"},"share":{"title":"共有","description":"3D成果物を簡単に共有。","icon":"🌐"},"fast":{"title":"高速生成","description":"最適化されたクラウド処理で素早く生成。","icon":"⚡"}}},"users":{"title":"対象ユーザー","tags":[{"title":"ゲーム開発","icon":"🎮"},{"title":"3Dクリエイター","icon":"🧊"},{"title":"建築","icon":"🏛️"},{"title":"プロダクトデザイン","icon":"💡"},{"title":"モデリング好き","icon":"🧩"},{"title":"クリエイティブ職","icon":"🎨"},{"title":"教育","icon":"🎓"}]},"productIntro":{"sectionTitle":"主な特徴","items":["ワンクリック画像→3D：写真や画像を読み込むだけで自動的に3Dモデルを生成し、素早く反復・調整できます。","WYSIWYGプレビュー：組み込みの3Dビューアーで回転・ズーム・複数のライティングプリセットを使えます。","複数フォーマットで出力：GLB/STL形式で出力し、主要なエンジンやスライサーで編集を続けられます。","タスクキューと履歴：作業は自動的に記録され、いつでも再ダウンロードや管理が可能です。","オフラインキャッシュ：生成したモデルはネット接続なしでも閲覧できます。","多言語UI：中国語・英語・マレー語・日本語・韓国語などをサポート。"],"noteTitle":"重要な注意","noteBody":"本アプリは、編集可能なベースモデルをワンクリックで素早く生成することに注力しています。自動生成は手作業のような細部まで到達しない場合もあるため、より緻密な精度や良好なトポロジーを求めるなら、お好みの3D編集ソフトでさらに仕上げてください。"}},"koalaPage":{"title":"Koala Haventree","subtitle":"気持ちがそっと着地できる場所。","description":"Koala Haventree は、リラックスと自己内省のための穏やかな空間を提供するユニークなモバイルゲームです。「感情の木」を育て、森の生き物と触れ合い、自分だけの避難所を作れます。落ち着いたアートと遊びで、日常の喧騒から優しく離れられます。","storyIntro":{"title":"Koala Haventree — ストーリー","paragraphs":["今回は、感情に寄り添うAIアプリを磨き上げる初めての挑戦です。いちばん力を注いだのは「もっと話せるようにする」ことではなく、距離感を学ばせることでした。より人間らしく、より思いやりを持ち、あなたの感情を受け止めて安心して打ち明けられるように。","必要に応じて役割を切り替えられ、より“人”に近い口調で会話できます。冗談も言うけれど、節度はきちんと保つ——もう一言が必要なときは寄り添い、静かにそばにいる方がいいときは邪魔をしない。私たちはよく立ち止まって問い直します：それは「伴走」しているのか、それとも「干渉」しているのか。だから多くの選択は「もっと多く」ではなく、伴走を軸にしました。必要なときに現れ、必要なときに静かでいる。","守りたいのは一つだけ：あなたを理解しながらも、代わりに結論を出さないアプリ。必要なときに、静かで心地よく、吐き出せて、打ち明けられて、気持ちを記録できる場所を届けること。"]},"features":{"title":"機能","items":{"emotion_card":{"title":"感情カード","description":"カードを引いて今の気持ちを見つめます。","icon":"🃏"},"ai_chat":{"title":"AIチャット","description":"かわいいコアラの相棒にいつでも話しかけられます。","icon":"💬"},"venting_hole":{"title":"木の穴","description":"つらい気持ちを木の穴に預けて手放します。","icon":"🌳"},"diary":{"title":"日記","description":"日々の出来事や心の動きを記録します。","icon":"✍️"},"ai_report":{"title":"AIレポート","description":"記録から気づきをまとめて自己理解を支援。","icon":"📊"},"achievements":{"title":"実績","description":"収集・チャット・記録で特別な実績を解放。","icon":"🏆"}}},"users":{"title":"おすすめの人","tags":[{"title":"記録が好き","icon":"📒"},{"title":"心のケア","icon":"❤️"},{"title":"忙しい毎日","icon":"⚡"},{"title":"ストレス軽減","icon":"🍃"},{"title":"話し相手が欲しい","icon":"🧸"},{"title":"心の平穏","icon":"🧘"}]},"productIntro":{"mainTitle":"主な特徴","sections":[{"title":"チャット＆リフレクト（AI生成）","items":["穏やかで支えあう空間で思いを語ってみましょう","優しいヒントが、感じていることとその意味を言葉にする手助けをします"]},{"title":"ツリーホール（プライベートに吐き出す）","items":["専用の“ツリーホール”にいつでも悩みを置いてきてください","評価せず、ただ解放し次へ進む場です"]},{"title":"ムードカード","items":["エモーションカードで素早い洞察と励ましを得ましょう","小さなリマインダーが別の視点をくれて、歩みを止めません"]},{"title":"フォトジャーナル","items":["日記を書き、瞬間を残したいときに写真も撮りましょう","端末から写真をアップロードして思い出をまとめてもOK","自分だけの感情・物語・成長のタイムラインをつくりましょう"]},{"title":"週刊インサイト","items":["アプリ内の活動（例：日記/ツリーホールの傾向）をもとにシンプルなまとめ","プレッシャーなくパターンに気づくヒントになります"]}],"noteTitle":"重要なお知らせ","noteBody":"Koala Haventree はサポート的な AI 生成コンテンツとジャーナリングツールを提供しますが、医療アプリではなく、診断や治療は行いません。危険を感じている、あるいは自傷を考えている場合は、すぐに地元の緊急サービスや信頼できる専門家にご相談ください。"}},"footer":{"privacyPolicy":"プライバシーポリシー","termsOfService":"利用規約"}}'))},69574,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"혁신 주도","desc":"최신 AI를 모든 크리에이티브 프로젝트에 녹여 경계를 확장하고 가능성을 넓힙니다."},"design":{"title":"디자인 미학","desc":"탁월한 시각 경험을 추구합니다—픽셀 하나까지 세심하게 다듬습니다."},"quality":{"title":"품질 보장","desc":"엄격한 품질 기준—모든 결과물에 우리의 기준을 담습니다."},"experience":{"title":"경험 중심","desc":"사용자 여정부터 인터랙션 디테일까지—더 명확하고 부드럽고 쉽게 만듭니다."},"maintenance":{"title":"지속적 유지보수","desc":"출시는 시작일 뿐—수정, 최적화, 반복 개선으로 경험을 꾸준히 끌어올립니다."},"security":{"title":"보안 및 개인정보 보호","desc":"데이터 보호는 저희의 최우선 과제입니다. 업계 최고의 보안 조치를 사용하여 고객님의 정보가 안전하고 기밀로 유지되도록 보장합니다."}},"feedbackButton":"피드백 보내기","feedbackCardTitle":"의견이나 영감을 들려주세요","feedbackCardDesc":["언제든지 문제를 제보하거나 아이디어·제안을 보내주세요. 모든 메시지를 꼼꼼히 읽고 지속적으로 개선해 더 나은 제품을 만들겠습니다. 사용 중 불편했던 점과 기대하는 부분, 앞으로 추가·개선되었으면 하는 방향을 알려주시면 좋아요. 가능하다면 사용 상황, 스크린샷, 재현 단계도 함께 보내주시면 더 빠르게 확인하고 개선할 수 있습니다.","크리에이티브 협업을 원하시거나 팀에 합류하고 싶으시다면 언제든지 연락 주세요."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"한 장의 이미지로 사용할 수 있는 3D 모델을 빠르게 생성하고, 모바일에서 실시간 미리보기, GLB/STL로 손쉽게 내보내기. 3D 지식 없이도, 보이는 그대로.","description":"촬영 → 생성 → 미리보기 → 내보내기, 한 번에 끝.","details":{"intro":"3D-PaiLiTi는 한 장의 이미지로 사용 가능한 3D 모델을 만들고, 모바일에서 실시간으로 확인한 뒤 GLB/STL로 내보낼 수 있어요. 3D 경험이 없어도 됩니다.","featureTitle":"핵심 기능","items":["원클릭 이미지→3D: 사진/이미지를 가져오면 자동으로 3D 모델 생성(편집 가능한 초안/러프 모델에 적합).","WYSIWYG 미리보기: 회전/확대 및 다양한 조명 프리셋을 지원하는 내장 3D 뷰어.","다양한 내보내기: GLB/STL로 내보내 일반적인 도구에서 계속 편집.","작업 큐 & 히스토리: 생성 작업을 자동 기록해 언제든 다운로드/관리.","오프라인 캐시: 생성된 모델을 오프라인에서도 확인.","다국어 UI: 여러 언어 지원."]}},"koala":{"title":"Koala Haventree","subtitle":"감정이 숨 쉴 수 있는 아늑하고 사적인 공간.\\n동반자가 필요할 땐 대화하고, 정리가 필요할 땐 기록하고, 부드러운 도구로 마음속에 남은 것을 내려놓아요.","description":"감정이 잠시 머무를 수 있는 부드러운 곳.","details":{"sections":[{"title":"🗣️ Chat & Reflect (AI‑generated)","items":["차분하고 지지적인 공간에서 생각을 정리하며 대화하세요","무엇을 느끼는지, 왜 중요한지 이름 붙일 수 있도록 부드럽게 안내합니다"]},{"title":"🕳️ The Tree Hole (비공개 털어놓기)","items":["언제든 개인 ‘트리 홀’에 걱정을 내려놓을 수 있어요","판단 없이—비우고 앞으로 나아가기 위한 공간"]},{"title":"🎴 Mood Cards","items":["감정 카드를 뽑아 빠른 통찰과 격려를 얻어요","관점을 바꾸고 계속 나아가게 해주는 작은 리마인더"]},{"title":"📓 Photo Journal","items":["기록하고 싶은 날엔 일기를 쓰고 사진으로 순간을 남겨요","또는 기기에서 사진을 업로드해 추억을 함께 보관해요","감정·이야기·성장의 타임라인을 만들어가요"]},{"title":"📊 Weekly Insights","items":["앱 활동(예: 일기/털어놓기 추세)을 기반으로 한 간단한 요약","압박 없이 패턴을 알아차리도록 돕습니다"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"한 장의 이미지로 사용 가능한 3D 모델을 만들고, 모바일에서 실시간으로 확인한 뒤 GLB/STL로 내보낼 수 있어요. 3D 경험이 없어도 됩니다.","description":"3D-PaiLiTi는 고급 AI 기술로 2D 이미지를 고품질 3D 모델로 변환합니다. 사진 한 장만 업로드하면 상세한 3D 모델을 자동 생성하고 실시간으로 확인 및 내보내기 할 수 있어요. 디자이너, 개발자, 취미 사용자 모두에게 적합합니다.","storyIntro":{"title":"3D-PaiLiTi — 이야기","paragraphs":["처음의 작은 영감이 휴대폰에서 진짜로 살아 움직이는 무언가가 되기까지, 그 과정은 결코 쉽지 않았어요. 막히기도 했고, 실수도 있었고, 작은 기쁨도 있었습니다.","저에게 이것은 단순한 앱이 아니라 ‘아이디어를 현실로 바꾸는’ 배움의 여정에 더 가깝습니다. 아직 완벽하진 않지만, 모든 디테일에 우리의 마음을 담았습니다. 그 진심과 온기가 당신에게도 전해지길 바랍니다."]},"features":{"title":"기능","items":{"ai_modeling":{"title":"AI 모델링","description":"원클릭으로 2D 이미지를 3D 모델로 변환합니다.","icon":"🎨"},"export":{"title":"다양한 내보내기","description":"GLB, STL 등 주요 3D 포맷을 지원합니다.","icon":"📦"},"preview":{"title":"미리보기","description":"실시간 360° 보기와 환경 프리셋 전환.","icon":"👁️"},"optimization":{"title":"AI 최적화","description":"더 안정적인 결과를 위한 스마트 보정/스타일.","icon":"🔄"},"share":{"title":"공유","description":"3D 결과물을 손쉽게 공유합니다.","icon":"🌐"},"fast":{"title":"빠른 생성","description":"최적화된 클라우드 프로세스로 빠르게 생성합니다.","icon":"⚡"}}},"users":{"title":"추천 대상","tags":[{"title":"게임 개발자","icon":"🎮"},{"title":"3D 크리에이터","icon":"🧊"},{"title":"건축/설계","icon":"🏛️"},{"title":"프로덕트 디자이너","icon":"💡"},{"title":"모델링 애호가","icon":"🧩"},{"title":"크리에이티브 직군","icon":"🎨"},{"title":"교육","icon":"🎓"}]},"productIntro":{"sectionTitle":"핵심 기능","items":["원클릭 이미지→3D: 사진이나 이미지를 가져오기만 하면 3D 모델이 자동 생성되어 빠르게 반복하고 다듬을 수 있어요.","WYSIWYG 미리보기: 내장 3D 뷰어에서 회전, 확대/축소, 다양한 라이트 프리셋을 사용할 수 있어요.","여러 내보내기 형식: GLB/STL로 내보내어 인기 엔진과 슬라이서에서 계속 편집할 수 있어요.","작업 대기열 및 기록: 작업이 자동 저장되어 언제든 재다운로드하고 관리할 수 있어요.","오프라인 캐시: 생성된 모델은 네트워크 없이도 확인 가능해요.","다국어 UI: 중국어, 영어, 말레이어, 일본어, 한국어 등 다양한 언어를 지원해요."],"noteTitle":"중요 안내","noteBody":"이 앱은 편집 가능한 기본 모델을 원클릭으로 빠르게 만드는 데 집중합니다. 자동 생성은 수작업 수준의 정밀도를 늘 구현하지 않을 수 있으니, 더 높은 정확도와 우수한 토폴로지가 필요하다면 선호하는 3D 편집 도구에서 추가로 다듬으세요."}},"koalaPage":{"title":"Koala Haventree","subtitle":"감정이 잠시 머무를 수 있는 부드러운 곳.","description":"Koala Haventree는 휴식과 자기 성찰을 위한 평온한 공간을 제공하는 독특한 모바일 게임입니다. ‘감정 나무’를 키우고 숲의 생명체와 교감하며 나만의 안식처를 만들 수 있어요. 잔잔한 아트 스타일과 플레이로 일상의 소음에서 잠시 벗어나도록 돕습니다.","storyIntro":{"title":"Koala Haventree — 이야기","paragraphs":["이번에는 감정을 담은 AI 앱을 다듬는 첫 시도입니다. 우리가 가장 공을 들인 것은 “더 말을 잘하게” 만드는 것이 아니라, ‘거리감’을 알게 하는 일이었어요. 더 인간적이고 더 섬세하게, 당신의 감정을 받아주고 안심하고 털어놓을 수 있게요.","필요에 따라 다양한 역할로 전환할 수 있어, 사람에 가까운 말투로 대화합니다. 농담도 하지만 선을 지키고—한마디 더가 필요할 땐 곁에 있고, 조용히 함께하는 게 좋을 땐 방해하지 않아요. 우리는 자주 스스로 묻습니다: 이건 동행인가, 방해인가? 그래서 많은 선택은 “더 많이”가 아니라, ‘동행’을 중심에 두었습니다. 나타나야 할 때 나타나고, 조용해야 할 때 조용히.","우리가 지키고 싶은 건 하나입니다: 당신을 이해하되 대신 결론 내리지 않는 앱. 필요할 때, 조용하고 편안하게 털어놓고, 이야기하고, 감정을 기록할 수 있는 공간을 드리고 싶습니다."]},"features":{"title":"기능","items":{"emotion_card":{"title":"감정 카드","description":"감정 카드를 뽑아 마음의 움직임을 살펴봐요.","icon":"🃏"},"ai_chat":{"title":"AI 채팅","description":"귀여운 코알라 친구에게 언제든 털어놓을 수 있어요.","icon":"💬"},"venting_hole":{"title":"트리 홀","description":"불편한 감정과 비밀을 안전하게 맡기고 내려놓아요.","icon":"🌳"},"diary":{"title":"일기","description":"하루의 기록과 마음 이야기를 남겨요.","icon":"✍️"},"ai_report":{"title":"AI 리포트","description":"기록을 바탕으로 정리된 인사이트를 제공합니다.","icon":"📊"},"achievements":{"title":"업적","description":"수집, 대화, 기록으로 특별한 업적을 해금해요.","icon":"🏆"}}},"users":{"title":"추천 대상","tags":[{"title":"기록을 좋아함","icon":"📒"},{"title":"감정 케어","icon":"❤️"},{"title":"바쁜 일상","icon":"⚡"},{"title":"스트레스 완화","icon":"🍃"},{"title":"동반자가 필요함","icon":"🧸"},{"title":"내면의 평온","icon":"🧘"}]},"productIntro":{"mainTitle":"핵심 기능","sections":[{"title":"채팅 & 리플렉트 (AI 생성)","items":["차분하고 지지하는 공간에서 생각을 털어놓으세요","부드러운 안내가 당신의 감정과 그 의미를 정리하도록 도와줍니다"]},{"title":"트리홀 (프라이빗하게 털어놓기)","items":["언제든지 개인적인 “트리 홀”에 걱정을 내려놓으세요","평가 없이 감정을 비우고 다음 걸음을 이어갈 수 있는 장소입니다"]},{"title":"무드 카드","items":["감정 카드를 뽑아 빠른 통찰과 응원을 받으세요","작은 알림이 시선을 바꾸고 계속 나아가도록 이끌어줍니다"]},{"title":"포토 저널","items":["일기를 쓰고 그 순간을 담고 싶다면 사진도 찍어보세요","기기에서 사진을 업로드해 추억을 함께 보관해도 좋아요","감정과 이야기, 성장 과정을 담은 나만의 타임라인을 만들어보세요"]},{"title":"주간 인사이트","items":["앱에서의 활동(예: 일기/트리 홀 트렌드) 기반 간단한 요약","압박 없이 패턴을 발견하는 데 도움을 줍니다"]}],"noteTitle":"중요 안내","noteBody":"Koala Haventree는 AI 생성 콘텐츠와 저널링 도구를 통해 지지적인 경험을 제공합니다. 의료 앱이 아니며 진단이나 치료를 제공하지 않습니다. 위험에 처했거나 자해를 생각하고 있다면 즉시 지역 응급 서비스나 신뢰할 수 있는 전문가에게 연락하세요."}},"footer":{"privacyPolicy":"개인정보 처리방침","termsOfService":"서비스 이용약관"}}'))},1385,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"Dipacu Inovasi","desc":"Kami menggabungkan AI termaju ke dalam setiap projek kreatif—meneroka sempadan baharu dan membuka peluang tanpa had."},"design":{"title":"Estetika Reka Bentuk","desc":"Mengutamakan pengalaman visual yang memukau—setiap piksel digarap dengan teliti."},"quality":{"title":"Jaminan Kualiti","desc":"Sistem kualiti yang ketat—setiap hasil mencerminkan komitmen kami terhadap kecemerlangan."},"experience":{"title":"Pengalaman Teras","desc":"Daripada perjalanan pengguna hingga perincian interaksi—kami perhalusi supaya lebih jelas, lancar dan mudah digunakan."},"maintenance":{"title":"Penyelenggaraan Berterusan","desc":"Pelancaran bukan penamat—baik pulih, penambahbaikan dan iterasi berterusan untuk pengalaman yang semakin baik."},"security":{"title":"Keselamatan & Privasi","desc":"Melindungi data anda adalah keutamaan kami. Kami menggunakan langkah-langkah keselamatan yang terkemuka dalam industri untuk memastikan maklumat anda selamat dan sulit."}},"feedbackButton":"Hantar maklum balas","feedbackCardTitle":"Kongsi komen atau inspirasi anda","feedbackCardDesc":["Anda dialu-alukan untuk berkongsi masalah atau menghantar idea dan cadangan pada bila-bila masa. Kami membaca setiap maklum balas dan terus mengulang baik pulih untuk menjadikan produk lebih baik. Ceritakan halangan yang anda alami serta apa yang anda harapkan, atau cadangkan penambahbaikan dan ciri baharu yang anda inginkan. Jika boleh, sertakan konteks penggunaan, tangkapan skrin atau langkah untuk ulang hasil—ini membantu kami mengesan dan memperbaiki dengan lebih cepat.","Jika anda berminat untuk bekerjasama secara kreatif atau menyertai pasukan, sila hubungi kami bila-bila masa."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"Hasilkan model 3D yang boleh digunakan daripada satu imej, pratonton masa nyata di telefon, dan eksport GLB/STL dengan mudah. Tak perlu asas 3D—apa yang anda lihat itulah hasilnya.","description":"Ambil gambar → Jana → Pratonton → Eksport. Siap sekali jalan.","details":{"intro":"3D-PaiLiTi menukar satu imej kepada model 3D yang boleh digunakan, dengan pratonton masa nyata di telefon dan eksport GLB/STL—tanpa pengalaman 3D.","featureTitle":"Ciri utama","items":["Imej→3D sekali klik: import foto/imej untuk jana model 3D secara automatik (sesuai untuk draf boleh sunting).","Pratonton WYSIWYG: penonton 3D terbina dalam dengan putar/zoom dan preset pencahayaan.","Pelbagai format eksport: eksport GLB/STL untuk sambung suntingan dalam alat biasa.","Queue & sejarah: rekod tugas automatik untuk muat turun dan urus bila‑bila masa.","Cache luar talian: model yang dijana boleh dilihat tanpa internet.","UI berbilang bahasa: menyokong pelbagai bahasa."]}},"koala":{"title":"Koala Haventree","subtitle":"Ruang yang selesa dan peribadi untuk emosi anda bernafas.\\nBerbual bila perlukan teman, menulis bila perlukan kejelasan, dan gunakan alat lembut untuk melepaskan yang terpendam.","description":"Tempat lembut untuk emosi anda berehat.","details":{"sections":[{"title":"🗣️ Chat & Reflect (AI-generated)","items":["Luahkan fikiran dalam ruang yang tenang dan menyokong","Prompt lembut untuk membantu anda menamakan apa yang dirasa dan mengapa ia penting"]},{"title":"🕳️ The Tree Hole (Vent privately)","items":["Lepaskan kerisauan ke dalam “tree hole” peribadi pada bila‑bila masa","Tanpa penghakiman—sekadar ruang untuk mengosongkan beban dan bergerak ke hadapan"]},{"title":"🎴 Mood Cards","items":["Tarik kad emosi untuk insight ringkas dan galakan","Peringatan kecil untuk membingkai semula dan teruskan"]},{"title":"📓 Photo Journal","items":["Tulis diari dan ambil foto untuk merakam momen","Atau muat naik foto dari peranti untuk simpan kenangan bersama","Bina garis masa perasaan, cerita dan perkembangan anda"]},{"title":"📊 Weekly Insights","items":["Ringkasan mudah berdasarkan aktiviti dalam aplikasi (cth. trend menulis/venting)","Membantu nampak corak—tanpa tekanan"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"Menukar satu imej kepada model 3D yang boleh digunakan, dengan pratonton masa nyata di telefon dan eksport GLB/STL—tanpa pengalaman 3D.","description":"3D-PaiLiTi ialah aplikasi inovatif yang menggunakan AI canggih untuk menukar imej 2D kepada model 3D berkualiti tinggi. Muat naik satu foto, algoritma akan menjana model terperinci yang boleh dipratonton serta‑merta dan dieksport. Sesuai untuk pereka, pembangun dan peminat.","storyIntro":{"title":"3D-PaiLiTi — Kisah","paragraphs":["Dari ilham pertama hingga benar‑benar “hidup” di telefon, perjalanannya penuh liku—ada yang tersekat, ada yang tersilap, dan ada juga kegembiraan kecil.","Bagi saya, ia bukan sekadar sebuah aplikasi; ia lebih seperti perjalanan belajar untuk mengubah idea menjadi nyata. Mungkin belum sempurna, tetapi setiap perincian membawa kesungguhan kami. Harap anda dapat merasai keikhlasan dan kehangatan itu."]},"features":{"title":"Ciri","items":{"ai_modeling":{"title":"Pemodelan AI","description":"Tukar 2D kepada 3D sekali klik dengan algoritma AI.","icon":"🎨"},"export":{"title":"Eksport pelbagai format","description":"Sokong GLB, STL dan format popular lain.","icon":"📦"},"preview":{"title":"Pratonton","description":"Lihat model 360° masa nyata dengan persekitaran boleh ditukar.","icon":"👁️"},"optimization":{"title":"Pengoptimuman AI","description":"Pelarasan pintar dan gaya untuk hasil lebih stabil.","icon":"🔄"},"share":{"title":"Kongsi","description":"Kongsi hasil 3D dengan mudah.","icon":"🌐"},"fast":{"title":"Pantas","description":"Proses awan dioptimumkan untuk model yang cepat dan boleh guna.","icon":"⚡"}}},"users":{"title":"Sesuai untuk","tags":[{"title":"Pembangun permainan","icon":"🎮"},{"title":"Pencipta 3D","icon":"🧊"},{"title":"Arkitek","icon":"🏛️"},{"title":"Pereka produk","icon":"💡"},{"title":"Peminat model","icon":"🧩"},{"title":"Pekerja kreatif","icon":"🎨"},{"title":"Pendidik","icon":"🎓"}]},"productIntro":{"sectionTitle":"Ciri Utama","items":["Satu klik gambar ke 3D: import foto atau imej dan jana model 3D secara automatik untuk iterasi dan penyempurnaan pantas.","Pratonton WYSIWYG: penonton 3D terbina menyokong putaran, zum dan pelbagai pratetapan pencahayaan.","Pelbagai format eksport: eksport kepada GLB/STL untuk penyuntingan lanjut dalam enjin dan perisian pemotong popular.","Barisan tugasan & sejarah: tugasan disimpan automatik supaya boleh dimuat turun semula dan diurus bila-bila masa.","Cache luar talian: model yang dijana boleh dilihat walaupun tanpa sambungan.","Antara muka pelbagai bahasa: menyokong Cina, Inggeris, Melayu, Jepun, Korea dan banyak lagi."],"noteTitle":"Nota Penting","noteBody":"Aplikasi ini memberi fokus kepada penjanaan pantas satu klik bagi model asas yang boleh disunting. Automasi mungkin tidak mencapai tahap perincian tangan; untuk ketepatan lebih tinggi dan topologi lebih baik, teruskan penyempurnaan dalam perisian 3D pilihan anda."}},"koalaPage":{"title":"Koala Haventree","subtitle":"Tempat lembut untuk emosi anda berehat.","description":"Koala Haventree ialah permainan mudah alih yang unik, menyediakan ruang yang tenang dan selesa untuk relaks dan refleksi diri. Anda boleh menanam “pokok emosi”, berinteraksi dengan makhluk hutan yang lembut, dan membina tempat perlindungan peribadi. Gaya seni dan permainan yang menenangkan membantu anda mencari ketenangan seketika.","storyIntro":{"title":"Koala Haventree — Kisah","paragraphs":["Kali ini, kami pertama kali cuba memoles sebuah aplikasi AI yang beremosi. Usaha terbesar kami bukanlah untuk “buat ia lebih petah bercakap”, tetapi untuk ajar ia tentang batas: lebih manusiawi, lebih peka, mampu menyambut emosi anda dan membuat anda rasa selamat untuk meluah.","Anda boleh menukar peranan mengikut keperluan supaya ia berbual dengan nada yang lebih seperti manusia—boleh bergurau, dan pada masa yang sama pandai menjaga batas: hadir bila perlu berkata lebih, dan senyap menemani bila tidak wajar mengganggu. Kami sering bertanya: adakah ia menemani anda, atau mengganggu anda? Jadi banyak keputusan bukan untuk buat “lebih banyak”, tetapi menjadikan peneman sebagai teras: muncul bila patut, diam bila lebih baik.","Kami mahu pegang satu perkara: membina aplikasi yang memahami anda tanpa membuat kesimpulan bagi pihak anda—dan bila anda perlukan, memberi ruang yang tenang dan selesa untuk melepaskan, berkongsi, dan merekod perasaan."]},"features":{"title":"Ciri","items":{"emotion_card":{"title":"Kad emosi","description":"Tarik kad emosi untuk meneroka perasaan anda.","icon":"🃏"},"ai_chat":{"title":"Sembang AI","description":"Berbual bila‑bila masa dengan rakan koala yang comel.","icon":"💬"},"venting_hole":{"title":"Tree hole","description":"Serahkan rasa tidak senang dan rahsia dengan selamat untuk dilepaskan.","icon":"🌳"},"diary":{"title":"Diari","description":"Catat momen harian dan cerita hati anda.","icon":"✍️"},"ai_report":{"title":"Laporan AI","description":"Ringkasan berdasarkan catatan untuk memahami diri dengan lebih baik.","icon":"📊"},"achievements":{"title":"Pencapaian","description":"Buka pencapaian unik melalui koleksi, sembang dan rekod.","icon":"🏆"}}},"users":{"title":"Sesuai untuk","tags":[{"title":"Suka mencatat","icon":"📒"},{"title":"Kesejahteraan emosi","icon":"❤️"},{"title":"Hidup pantas","icon":"⚡"},{"title":"Kurangkan tekanan","icon":"🍃"},{"title":"Perlukan teman","icon":"🧸"},{"title":"Cari ketenangan","icon":"🧘"}]},"productIntro":{"mainTitle":"Ciri utama","sections":[{"title":"Berbual & Renungkan (AI)","items":["Bercerita tentang fikiran anda di ruang yang tenang dan menyokong","Petunjuk lembut membantu anda menyatakan apa yang anda rasa dan mengapa ia penting"]},{"title":"Lubang Pokok (Luahkan secara peribadi)","items":["Lepaskan kerisauan ke dalam “tree hole” peribadi bila-bila masa","Tanpa penghakiman—sekadar tempat untuk melepaskan dan meneruskan"]},{"title":"Kad Emosi","items":["Keluarkan kad emosi untuk pandangan cepat dan galakan","Peringatan kecil membantu anda melihat dari sudut lain dan terus bergerak"]},{"title":"Jurnal Foto","items":["Tulis entri jurnal dan ambil gambar bila anda mahu abadikan detik","Atau muat naik gambar dari peranti untuk menyimpan kenangan bersama","Bina garis masa anda sendiri tentang perasaan, kisah dan pertumbuhan"]},{"title":"Wawasan Mingguan","items":["Ringkasan mudah berdasarkan aktiviti dalam aplikasi (contohnya, trend jurnal / tree hole)","Membantu anda mengenal pasti corak tanpa tekanan"]}],"noteTitle":"Nota penting","noteBody":"Koala Haventree menyediakan kandungan dan alat jurnal yang disokong AI. Ia bukan aplikasi perubatan dan tidak menyediakan diagnosis atau rawatan. Jika anda dalam bahaya atau memikirkan kemudaratan diri, sila hubungi perkhidmatan kecemasan tempatan atau profesional dipercayai dengan segera."}},"footer":{"privacyPolicy":"Dasar Privasi","termsOfService":"Terma Perkhidmatan"}}'))},64253,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"Inovação","desc":"Integramos IA de ponta em cada projeto criativo—quebrando limites e abrindo novas possibilidades."},"design":{"title":"Estética","desc":"Buscamos experiências visuais excepcionais—cada pixel é cuidadosamente trabalhado."},"quality":{"title":"Qualidade","desc":"Um sistema rigoroso de qualidade—cada entrega reflete nossa busca por excelência."},"experience":{"title":"Experiência no Centro","desc":"Do fluxo do usuário aos detalhes de interação—refinamos tudo para ficar claro, suave e fácil de usar."},"maintenance":{"title":"Manutenção Contínua","desc":"O lançamento é só o começo—correções, otimizações e iterações para melhorar com o tempo."},"security":{"title":"Segurança e Privacidade","desc":"Proteger seus dados é nossa principal prioridade. Usamos medidas de segurança líderes do setor para garantir que suas informações estejam seguras e confidenciais."}},"feedbackButton":"Enviar feedback","feedbackCardTitle":"Compartilhe seu feedback ou inspiração","feedbackCardDesc":["Você pode nos enviar problemas, ideias e sugestões a qualquer momento. Lemos cada mensagem e seguimos iterando para melhorar o produto. Compartilhe o que atrapalhou seu uso e o que você espera, ou o que gostaria que adicionássemos ou aprimorássemos no futuro. Se puder, inclua o contexto de uso, capturas de tela ou passos para reproduzir — isso nos ajuda a identificar e melhorar mais rápido.","Se você tem interesse em colaboração criativa ou em se juntar ao time, fale conosco quando quiser."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"Gere modelos 3D utilizáveis a partir de uma única imagem, pré-visualize em tempo real no celular e exporte para GLB/STL. Não precisa de conhecimento em 3D: o que você vê é o que você obtém.","description":"Foto → Gerar → Pré-visualizar → Exportar. Tudo de uma vez.","details":{"intro":"3D-PaiLiTi transforma uma imagem em um modelo 3D utilizável, com prévia em tempo real no celular e exportação GLB/STL—sem precisar de experiência em 3D.","featureTitle":"Recursos principais","items":["Imagem→3D em um clique: importe uma foto e gere automaticamente um modelo 3D (ótimo como rascunho editável).","Prévia WYSIWYG: visualizador 3D integrado com rotação/zoom e presets de iluminação.","Vários formatos: exporte para GLB/STL e continue editando em ferramentas comuns.","Fila e histórico: registra tarefas automaticamente para baixar e gerenciar quando quiser.","Cache offline: modelos gerados podem ser vistos offline.","Interface multilíngue: suporte a vários idiomas."]}},"koala":{"title":"Koala Haventree","subtitle":"Um espaço acolhedor e privado para suas emoções respirarem.\\nConverse quando precisar de companhia, escreva quando precisar de clareza e use ferramentas gentis para soltar o que ficou preso.","description":"Um lugar gentil para suas emoções pousarem.","details":{"sections":[{"title":"🗣️ Chat & Reflect (IA)","items":["Converse sobre seus pensamentos em um espaço calmo e acolhedor","Sugestões gentis para nomear o que você sente e por que importa"]},{"title":"🕳️ The Tree Hole (Desabafe em privado)","items":["Deposite suas preocupações em um “tree hole” privado a qualquer momento","Sem julgamento—um lugar para aliviar e seguir em frente"]},{"title":"🎴 Mood Cards","items":["Tire cartas de emoção para insight rápido e incentivo","Pequenos lembretes para reenquadrar e continuar"]},{"title":"📓 Diário com fotos","items":["Escreva entradas e tire uma foto quando quiser guardar o momento","Ou envie uma foto do seu dispositivo para manter memórias juntas","Construa sua própria linha do tempo de sentimentos, histórias e crescimento"]},{"title":"📊 Insights semanais","items":["Resumos simples com base na sua atividade (ex.: tendências de diário/desabafo)","Ajuda a notar padrões—sem pressão"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"Transforma uma imagem em um modelo 3D utilizável, com prévia em tempo real no celular e exportação GLB/STL—sem precisar de experiência em 3D.","description":"3D-PaiLiTi é um aplicativo inovador que usa IA avançada para transformar suas imagens 2D em modelos 3D de alta qualidade. Envie uma foto: o algoritmo gera um modelo detalhado para visualizar e exportar. Ideal para designers, desenvolvedores e entusiastas.","storyIntro":{"title":"3D-PaiLiTi — História","paragraphs":["De uma primeira ideia a algo que realmente ganha vida no celular, o caminho teve de tudo — travas, erros e pequenas alegrias.","Para mim, é mais do que um app; é uma jornada de aprendizado para transformar ideias em realidade. Talvez ainda não esteja perfeito, mas cada detalhe carrega o nosso cuidado. Espero que você sinta essa dedicação e esse calor."]},"features":{"title":"Recursos","items":{"ai_modeling":{"title":"Modelagem com IA","description":"Converta 2D em 3D em um clique com algoritmos avançados.","icon":"🎨"},"export":{"title":"Exportação multi‑formato","description":"Suporta GLB, STL e outros formatos populares.","icon":"📦"},"preview":{"title":"Prévia online","description":"Visualização 360° em tempo real com ambientes alternáveis.","icon":"👁️"},"optimization":{"title":"Otimização com IA","description":"Ajustes inteligentes e estilos para resultados mais estáveis.","icon":"🔄"},"share":{"title":"Compartilhar","description":"Compartilhe suas criações 3D com facilidade.","icon":"🌐"},"fast":{"title":"Geração rápida","description":"Processo em nuvem otimizado para obter modelos úteis rapidamente.","icon":"⚡"}}},"users":{"title":"Para quem é","tags":[{"title":"Desenvolvedores de jogos","icon":"🎮"},{"title":"Criadores 3D","icon":"🧊"},{"title":"Arquitetos","icon":"🏛️"},{"title":"Design de produto","icon":"💡"},{"title":"Fãs de modelagem","icon":"🧩"},{"title":"Profissionais criativos","icon":"🎨"},{"title":"Educação","icon":"🎓"}]},"productIntro":{"sectionTitle":"Recursos principais","items":["Imagem para 3D com um clique: importe uma foto ou imagem e gere automaticamente um modelo 3D para iterações e refinamentos rápidos.","Prévia WYSIWYG: o visualizador 3D integrado permite girar, aplicar zoom e alternar luzes pré-definidas.","Exportação em múltiplos formatos: exporte para GLB/STL e continue editando em engines e slicers populares.","Fila de tarefas e histórico: os jobs são salvos automaticamente para download e gerenciamento a qualquer momento.","Cache offline: modelos gerados podem ser visualizados mesmo sem conexão.","Interface multilíngue: compatível com chinês, inglês, malaio, japonês, coreano e outras línguas."],"noteTitle":"Observação importante","noteBody":"O app foca na geração rápida e com um clique de modelos base editáveis. A automação pode não alcançar o nível de detalhe artesanal; para mais precisão e melhor topologia, continue refinando no seu software 3D preferido."}},"koalaPage":{"title":"Koala Haventree","subtitle":"Um lugar gentil para suas emoções pousarem.","description":"Koala Haventree é um jogo mobile único que oferece um espaço tranquilo e acolhedor para relaxar e refletir. Nesse mundo pacífico, você pode cultivar “árvores de emoção”, interagir com criaturas da floresta e criar seu refúgio. Seu estilo calmante ajuda a encontrar momentos de paz.","storyIntro":{"title":"Koala Haventree — História","paragraphs":["Desta vez, é a nossa primeira tentativa de lapidar um app de IA com sensibilidade emocional. O maior trabalho não foi “fazer ele falar mais”, e sim ensinar limites: ser mais humano, mais cuidadoso, capaz de acolher suas emoções e te deixar seguro para se abrir.","Você pode alternar papéis conforme a necessidade, para que ele converse com um tom mais parecido com o de uma pessoa real — pode brincar com você e, ao mesmo tempo, saber medir: estar presente quando cabe dizer mais uma frase e ficar em silêncio quando é melhor não interromper. Muitas vezes nos perguntamos: ele está te acompanhando ou te atrapalhando? Por isso, várias escolhas não foram para fazer “mais”, mas para colocar o acolhimento no centro: aparecer quando deve e ficar quieto quando é melhor.","Queremos preservar uma coisa: criar um app que te entenda sem tirar conclusões por você — e que, quando você precisar, ofereça um lugar calmo e confortável para desabafar, conversar e registrar seus sentimentos."]},"features":{"title":"Recursos","items":{"emotion_card":{"title":"Cartas de emoção","description":"Tire uma carta para explorar como você se sente.","icon":"🃏"},"ai_chat":{"title":"Chat com IA","description":"Converse a qualquer hora com seu companheiro koala.","icon":"💬"},"venting_hole":{"title":"Tree hole","description":"Desabafe em privado para aliviar o peso.","icon":"🌳"},"diary":{"title":"Diário","description":"Registre momentos e sentimentos para guardar memórias.","icon":"✍️"},"ai_report":{"title":"Relatório com IA","description":"Sínteses a partir dos seus registros para se entender melhor.","icon":"📊"},"achievements":{"title":"Conquistas","description":"Desbloqueie conquistas ao coletar, conversar e registrar.","icon":"🏆"}}},"users":{"title":"Para quem é","tags":[{"title":"Gosta de registrar","icon":"📒"},{"title":"Bem‑estar emocional","icon":"❤️"},{"title":"Vida acelerada","icon":"⚡"},{"title":"Alívio do estresse","icon":"🍃"},{"title":"Busca companhia","icon":"🧸"},{"title":"Paz interior","icon":"🧘"}]},"productIntro":{"mainTitle":"Principais recursos","sections":[{"title":"Conversar & Refletir (IA)","items":["Fale sobre seus pensamentos em um espaço calmo e acolhedor","Sugestões suaves ajudam a nomear o que você sente e por que importa"]},{"title":"O Buraco da Árvore (Desabafe em privado)","items":["Coloque suas preocupações em um “buraco da árvore” privado quando quiser","Sem julgamentos — apenas um lugar para liberar e seguir em frente"]},{"title":"Cartas de humor","items":["Puxe cartas de humor para obter insights rápidos e encorajamento","Pequenos lembretes ajudam a ver de outro ângulo e continuar"]},{"title":"Diário fotográfico","items":["Escreva entradas e tire fotos sempre que quiser registrar o momento","Ou envie uma foto do seu dispositivo para manter as memórias juntinhas","Construa sua própria linha do tempo de emoções, histórias e crescimento"]},{"title":"Insights semanais","items":["Resumos simples baseados na sua atividade no app (ex: tendências de diário/desabafos)","Ajuda a notar padrões sem pressão"]}],"noteTitle":"Nota importante","noteBody":"Koala Haventree oferece conteúdos e ferramentas de diário gerados por IA. Não é um app médico e não fornece diagnóstico ou tratamento. Se você estiver em perigo ou pensando em se machucar, procure imediatamente os serviços de emergência locais ou um profissional de confiança."}},"footer":{"privacyPolicy":"Política de Privacidade","termsOfService":"Termos de Serviço"}}'))},86604,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"Драйв инноваций","desc":"Мы внедряем передовой ИИ в каждый креативный проект — расширяем границы и открываем новые возможности."},"design":{"title":"Эстетика дизайна","desc":"Стремимся к безупречному визуальному опыту — каждый пиксель продуман."},"quality":{"title":"Гарантия качества","desc":"Строгая система контроля — каждый результат отражает нашу планку."},"experience":{"title":"Опыт в центре","desc":"От пользовательского пути до микро‑деталей — доводим до ясности, плавности и удобства."},"maintenance":{"title":"Постоянная поддержка","desc":"Запуск — не финиш: исправления, оптимизации и итерации, чтобы продукт становился лучше."},"security":{"title":"Безопасность и Конфиденциальность","desc":"Защита ваших данных является нашим главным приоритетом. Мы используем передовые меры безопасности, чтобы обеспечить безопасность и конфиденциальность вашей информации."}},"feedbackButton":"Отправить отзыв","feedbackCardTitle":"Поделитесь мнением или идеей","feedbackCardDesc":["Вы можете в любое время написать нам о проблемах или отправить идеи и предложения. Мы читаем каждое сообщение и постоянно улучшаем продукт. Поделитесь тем, что мешает в использовании, и вашими ожиданиями, а также тем, что вы хотели бы добавить или улучшить. Очень помогут контекст использования, скриншоты или шаги для воспроизведения — так мы быстрее найдём причину и исправим.","Если вас интересует творческое сотрудничество или вы хотите присоединиться к команде, свяжитесь с нами в любое время."]},"carousel":{"items":{"pailiti":{"title":"3D-PaiLiTi","subtitle":"Быстро создавайте пригодные 3D‑модели из одного изображения, просматривайте в реальном времени на телефоне и экспортируйте в GLB/STL. Не нужны знания 3D — что видите, то и получаете.","description":"Фото → Генерация → Предпросмотр → Экспорт. Всё за один раз.","details":{"intro":"3D-PaiLiTi превращает одно изображение в пригодную 3D‑модель, даёт предпросмотр в реальном времени на телефоне и экспорт в GLB/STL — без опыта 3D.","featureTitle":"Ключевые возможности","items":["Image→3D в один клик: импортируйте фото и автоматически получите 3D‑модель (удобно как редактируемый черновик).","WYSIWYG‑просмотр: встроенный 3D‑просмотрщик с вращением/зумом и пресетами освещения.","Несколько форматов экспорта: GLB/STL для продолжения работы в популярных инструментах.","Очередь и история: задачи записываются автоматически — удобно скачивать и управлять.","Оффлайн‑кэш: модели доступны для просмотра без интернета.","Мультиязычный интерфейс: поддержка нескольких языков."]}},"koala":{"title":"Koala Haventree","subtitle":"Уютное и приватное пространство, где чувствам легче дышать.\\nОбщайтесь, когда нужна поддержка, пишите, когда нужна ясность, и используйте мягкие инструменты, чтобы отпустить то, что застряло внутри.","description":"Мягкое место, где чувствам можно приземлиться.","details":{"sections":[{"title":"🗣️ Chat & Reflect (AI-generated)","items":["Проговорите мысли в спокойном, поддерживающем пространстве","Мягкие подсказки помогут назвать чувства и понять, почему это важно"]},{"title":"🕳️ The Tree Hole (Приватный «слив»)","items":["Сбрасывайте тревоги в личную «дыру в дереве» в любой момент","Без осуждения — просто место, чтобы выдохнуть и двигаться дальше"]},{"title":"🎴 Карты настроения","items":["Тяните карты эмоций для быстрого инсайта и поддержки","Небольшие напоминания, которые помогают переформулировать и продолжать"]},{"title":"📓 Фото‑дневник","items":["Пишите записи и делайте фото, чтобы сохранить момент","Или загрузите фото с устройства, чтобы хранить воспоминания вместе","Создайте свою ленту чувств, историй и роста"]},{"title":"📊 Еженедельные инсайты","items":["Простые сводки по активности в приложении (например, тренды дневника/выговориться)","Помогает замечать закономерности — без давления"]}]}}}},"pailitiPage":{"title":"3D-PaiLiTi","subtitle":"Превращает одно изображение в пригодную 3D-модель, даёт предпросмотр в реальном времени на телефоне и экспорт в GLB/STL — без опыта 3D.","description":"3D-PaiLiTi использует продвинутый ИИ, чтобы превращать 2D‑изображения в качественные 3D‑модели. Просто загрузите фото — алгоритм создаст детальную модель, которую можно просматривать и экспортировать. Подходит дизайнерам, разработчикам и энтузиастам.","storyIntro":{"title":"3D-PaiLiTi — История","paragraphs":["От первой искры идеи до того, что по‑настоящему оживает на телефоне, путь оказался непростым — были тупики, ошибки и маленькие моменты радости.","Для меня это больше, чем приложение; это учебное путешествие по превращению идей в реальность. Возможно, пока не идеально, но в каждой детали — наша забота. Надеюсь, вы почувствуете эту искренность и тепло."]},"features":{"title":"Функции","items":{"ai_modeling":{"title":"ИИ‑моделирование","description":"Преобразование 2D→3D в один клик.","icon":"🎨"},"export":{"title":"Экспорт форматов","description":"Поддержка GLB, STL и других популярных форматов.","icon":"📦"},"preview":{"title":"Предпросмотр","description":"360° просмотр в реальном времени с разными окружениями.","icon":"👁️"},"optimization":{"title":"ИИ‑оптимизация","description":"Умные правки и стилизация для более стабильных результатов.","icon":"🔄"},"share":{"title":"Поделиться","description":"Легко делитесь 3D‑результатами.","icon":"🌐"},"fast":{"title":"Быстро","description":"Оптимизированный облачный процесс для быстрых моделей.","icon":"⚡"}}},"users":{"title":"Кому подойдёт","tags":[{"title":"Разработчики игр","icon":"🎮"},{"title":"3D‑создатели","icon":"🧊"},{"title":"Архитекторы","icon":"🏛️"},{"title":"Продукт‑дизайн","icon":"💡"},{"title":"Любители моделинга","icon":"🧩"},{"title":"Креативные специалисты","icon":"🎨"},{"title":"Образование","icon":"🎓"}]},"productIntro":{"sectionTitle":"Ключевые возможности","items":["Одним кликом из изображения в 3D: импортируйте фото или картинку и автоматически создавайте 3D-модель для быстрой итерации и доработки.","WYSIWYG-просмотр: встроенный 3D-вьюер поддерживает вращение, масштабирование и несколько предустановок света.","Несколько форматов экспорта: выводите в GLB/STL для дальнейшей работы в популярных движках и слайсерах.","Очередь задач и история: задания сохраняются автоматически, чтобы их можно было снова скачать и отредактировать в любой момент.","Офлайн-кэш: созданные модели остаются доступными даже без интернета.","Мультиязычный интерфейс: поддерживает китайский, английский, малайский, японский, корейский и другие языки."],"noteTitle":"Важное примечание","noteBody":"Приложение ориентировано на быструю генерацию редактируемых базовых моделей одним кликом. Автоматическое создание может не обеспечить такой же уровень деталей, как вручную; для большей точности и лучшей топологии дорабатывайте модель в любимом 3D-редакторе."}},"koalaPage":{"title":"Koala Haventree","subtitle":"Мягкое место, где чувствам можно приземлиться.","description":"Koala Haventree — уникальная мобильная игра, которая даёт спокойное и уютное пространство для отдыха и саморефлексии. Здесь вы выращиваете «деревья эмоций», общаетесь с лесными существами и создаёте личное убежище. Успокаивающий стиль помогает находить моменты тишины.","storyIntro":{"title":"Koala Haventree — История","paragraphs":["В этот раз мы впервые по‑настоящему шлифуем эмоционально ориентированное AI‑приложение. Больше всего сил ушло не на то, чтобы «сделать его разговорчивее», а на то, чтобы научить его чувству меры: быть человечнее, бережнее, уметь удерживать пространство для ваших эмоций и давать вам ощущение безопасности.","Вы можете переключать роли по настроению — чтобы тон звучал как у живого человека: он может пошутить, но и держит границы — скажет лишнее слово, когда это важно, и будет тихо рядом, когда лучше не вмешиваться. Мы часто спрашиваем себя: это поддержка или помеха? Поэтому многие решения были не про «больше», а про сопровождение как основу: появляться, когда нужно, и быть тихим, когда так лучше.","Мы хотим сохранить одно: сделать приложение, которое понимает вас, но не выносит вердиктов вместо вас — и, когда вам нужно, даёт спокойное, комфортное место, где можно выговориться, поделиться и записать свои чувства."]},"features":{"title":"Функции","items":{"emotion_card":{"title":"Карты эмоций","description":"Тяните карту эмоции, чтобы исследовать своё состояние.","icon":"🃏"},"ai_chat":{"title":"ИИ‑чат","description":"Общайтесь с милым коалой‑спутником в любое время.","icon":"💬"},"venting_hole":{"title":"Дупло","description":"Доверяйте тревоги и секреты «дуплу» — чтобы отпускать.","icon":"🌳"},"diary":{"title":"Дневник","description":"Записывайте моменты и настроение, сохраняйте воспоминания.","icon":"✍️"},"ai_report":{"title":"ИИ‑отчёт","description":"Инсайты по вашим записям — чтобы лучше понимать себя.","icon":"📊"},"achievements":{"title":"Достижения","description":"Открывайте достижения, собирая, общаясь и записывая.","icon":"🏆"}}},"users":{"title":"Кому подойдёт","tags":[{"title":"Любите записывать","icon":"📒"},{"title":"Эмоциональное благополучие","icon":"❤️"},{"title":"Быстрый ритм","icon":"⚡"},{"title":"Снижение стресса","icon":"🍃"},{"title":"Нужна поддержка","icon":"🧸"},{"title":"Внутреннее спокойствие","icon":"🧘"}]},"productIntro":{"mainTitle":"Основные функции","sections":[{"title":"Поговорить и осмыслить (ИИ)","items":["Обсудите свои мысли в спокойном, поддерживающем пространстве","Нежные подсказки помогают назвать чувства и понять, почему они важны"]},{"title":"Дупло (приватное выговаривание)","items":["В любое время откладывайте заботы в личное «дупло»","Без оценки — просто место, чтобы освободиться и идти дальше"]},{"title":"Карты настроения","items":["Тяните карты настроения для быстрых инсайтов и поддержки","Небольшие напоминания помогают посмотреть на ситуации по-новому и продолжать"]},{"title":"Фото-дневник","items":["Пишите дневник и делайте фото, когда хотите запечатлеть момент","Или загрузите фото с устройства, чтобы сохранить воспоминания","Создайте свою собственную хронологию чувств, историй и роста"]},{"title":"Еженедельные выводы","items":["Простые резюме на основе активности в приложении (например, тенденции дневника/дупла)","Помогает без давления замечать закономерности"]}],"noteTitle":"Важное примечание","noteBody":"Koala Haventree предлагает поддерживающий ИИ-контент и инструменты ведения дневника, но не является медицинским приложением и не предоставляет диагностику или лечение. Если вы в опасности или думаете о саморазрушении, свяжитесь немедленно с местными экстренными службами или надежным специалистом."}},"footer":{"privacyPolicy":"Политика конфиденциальности","termsOfService":"Условия обслуживания"}}'))},47772,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"创新驱动","desc":"将最前沿的AI技术融入每一个创意项目，突破传统边界，创造无限可能"},"design":{"title":"设计美学","desc":"追求极致的视觉体验，每个像素都经过精心雕琢，呈现令人惊叹的美感"},"quality":{"title":"品质保证","desc":"严格的质量控制体系，每个作品都代表着我们对卓越的不懈追求"},"experience":{"title":"以体验为核心","desc":"从用户路径到交互细节持续打磨，让产品更顺手、更清晰、更好用"},"maintenance":{"title":"持续维护","desc":"上线不止于交付，持续修复、优化与迭代，让体验长期稳定增长"},"security":{"title":"安全与隐私","desc":"保护您的数据是我们的首要任务。我们采用行业领先的安全措施，确保您的信息安全且保密。"}},"feedbackButton":"提交反馈","feedbackCardTitle":"点击这里向我们反馈","feedbackCardDesc":["欢迎随时向我们反馈问题或投递您的想法与建议。我们会认真阅读每一条反馈，持续优化迭代，把产品做得更好。您可以分享使用过程中遇到的阻碍与期待，也可以提出您希望未来新增或优化的方向。我们很欢迎你附上使用场景、截图或复现步骤，这会帮助我们更快定位与改进。","若您有意向与我们提供创意合作或者加入团队，欢迎随时与我们联系。"]},"carousel":{"items":{"pailiti":{"title":"3D-拍立体","subtitle":"让你能从一张图片快速生成可用的 3D 模型，在手机上实时预览，并轻松导出为 GLB/STL 格式。无需任何 3D 基础，真正做到所见即所得。","description":"拍照 -> 生成 -> 预览 -> 导出一次搞定","details":{"featureTitle":"核心功能","items":["一键图片转 3D：导入照片或图片即可自动生成 3D 模型（最适合作为可编辑的粗模或草稿，便于快速迭代和后续精修）。","所见即所得预览：内置 3D 查看器，支持旋转、缩放和多种环境光预设。","多种导出格式：可导出为 GLB/STL 格式，方便在主流引擎和切片软件中继续编辑。","任务队列与历史：自动记录生成任务，随时方便重新下载和管理。","本地缓存：生成的模型支持离线查看。","多语言界面：支持多种语言。"]}},"koala":{"title":"心窝森林","subtitle":"一个舒适、私密的空间，让你的感受得以呼吸。\\n需要陪伴时可以聊天，需要清晰时可以写作，并使用温和的工具来释放内心的郁结。","description":"让情绪轻轻落脚的地方。","details":{"sections":[{"title":"🗣️ 聊聊与自我梳理（AI 生成）","items":["在平静、支持性的空间里，把想法说出来","温柔的提示，帮助你说清自己在感受什么、为何重要"]},{"title":"🕳️ 树洞（私密倾诉）","items":["随时把烦恼丢进专属“树洞”","不评判，只负责承载，让你轻装继续"]},{"title":"🎴 情绪卡片","items":["抽取情绪卡，获得快速洞察与鼓励","小小提醒，帮你换个角度继续前行"]},{"title":"📓 照片日记","items":["想记录时写下日记，并拍一张照片定格当下","也可以从设备上传照片，把回忆放在一起","建立属于你的情绪、故事与成长时间线"]},{"title":"📊 每周洞察","items":["基于应用内活动的简要总结（如写日记/树洞趋势）","帮助你轻松发现模式——不带压力"]}]}}}},"pailitiPage":{"title":"3D-拍立体","subtitle":"让你能从一张图片快速生成可用的 3D 模型，在手机上实时预览，并轻松导出为 GLB/STL 格式。无需任何 3D 基础，真正做到所见即所得。","description":"3D-拍立体 是一款创新的应用，它利用先进的 AI 技术，将您的 2D 图片转化为高质量的 3D 模型。只需上传一张照片，我们的智能算法就会自动生成精细的 3D 模型，您可以实时预览并导出，用于各种项目。无论您是设计师、开发者还是业余爱好者，3D-拍立体 都能简化您的创作流程，开启全新的可能性维度。","storyIntro":{"title":"3D-拍立体 篇","paragraphs":["从最初的一个灵感，到真的能在手机上动起来，这一路其实经历了不少。有卡关、有失误，也有那些小小的喜悦。","对我来说，它不只是一个 App，更像是一段「把想法变成现实」的学习旅程。也许还不完美，但每个细节都包含着我们的用心。希望你也能感受到那份认真与温度。"]},"features":{"title":"特性展示","items":{"ai_modeling":{"title":"AI 智能建模","description":"先进 AI 算法，一键将 2D 图片转换为高质量 3D 模型","icon":"🎨"},"export":{"title":"多格式导出","description":"支持 GLB、STL 等主流 3D 格式，满足不同场景需求","icon":"📦"},"preview":{"title":"在线预览","description":"实时 360° 查看模型，多样化环境随心切换","icon":"👁️"},"optimization":{"title":"AI 优化","description":"智能改图与风格化，让生成效果更稳定","icon":"🔄"},"share":{"title":"一键分享","description":"轻松分享 3D 作品到社交平台或团队","icon":"🌐"},"fast":{"title":"极速生成","description":"优化的云端流程，快速获得可用 3D 模型","icon":"⚡"}}},"users":{"title":"适用人群","tags":[{"title":"热爱游戏创作","icon":"🎮"},{"title":"痴迷三维世界","icon":"🌍"},{"title":"构想未来空间","icon":"🚀"},{"title":"追求极致体验","icon":"💎"},{"title":"享受建模乐趣","icon":"🛠️"},{"title":"渴望高效工具","icon":"⚡"},{"title":"探索创新教学","icon":"🎓"}]},"productIntro":{"sectionTitle":"核心功能","items":["一键图片转 3D：导入照片或图片即可自动生成 3D 模型，快速迭代与后续精修。","所见即所得预览：内置 3D 查看器，支持旋转、缩放和多种环境光预设。","多种导出格式：可导出为 GLB/STL，便于在主流引擎与切片软件中继续编辑。","任务队列与历史：自动记录生成任务，随时重新下载与管理。","本地缓存：生成的模型支持离线查看。","多语言界面：支持中文、英文、马来语、日语、韩语等多种语言。"],"noteTitle":"重要提示","noteBody":"本应用侧重于快速一键生成和易于编辑的基础模型。受限于自动化生成技术，结果可能无法达到手工建模的超精细细节。如需更高精度细节与更优拓扑，建议在 3D 编辑软件中进一步优化。"}},"koalaPage":{"title":"心窝森林","subtitle":"让情绪轻轻落脚的地方。","description":"心窝森林是一款独特的手机游戏，它提供了一个宁静舒适的空间，供您放松和自我反思。在这个和平的世界里，您可以种植自己的“情绪树”，与温和的森林生物互动，并创建一个个性化的避风港。凭借其舒缓的艺术风格和宁静的游戏玩法，心窝森林提供了一个远离日常生活喧嚣的温柔避世之所，帮助您找到片刻的宁静和正念。","storyIntro":{"title":"心窝森林 篇","paragraphs":["这次是我们初次尝试打磨一个带有情感的 AI 应用。过程中，我们花最多力气的，其实不是“让它更会说”，而是让它更懂分寸、更人性化，更能接住你的情绪、让你安心倾诉。","你可以按需切换不同角色，让它用更像真人的语气来陪你聊天：会陪你开玩笑，也会拿捏好分寸——该多说一句时不缺席，该安静陪着时不打扰。我们常常停下来反问自己：它是在陪伴你，还是在打扰你？所以很多选择不是为了做得“更多”，而是以陪伴作为核心出发点：在该出现的时候出现、该安静的时候安静。","我们一直想守住一件事：制作一款了解你，但不替你下结论；只会在你需要的时候，给你一个安静、舒服、能发泄、能倾诉、也能记录心情的地方。"]},"features":{"title":"功能亮点","items":{"emotion_card":{"title":"情绪抽卡","description":"抽取你的专属情绪卡片，探索内心的每一次波动。","icon":"🃏"},"ai_chat":{"title":"AI聊天","description":"随时与可爱的无尾熊伙伴倾诉，分享你的喜怒哀乐。","icon":"💬"},"venting_hole":{"title":"发泄树洞","description":"将所有不愉快和秘密都安心地交给树洞，让心灵得到释放。","icon":"🌳"},"diary":{"title":"写日记","description":"记录每一天的生活点滴和心情故事，珍藏你的专属记忆。","icon":"✍️"},"ai_report":{"title":"AI报告","description":"根据你的记录，生成专业的情绪报告，帮你更好地了解自己。","icon":"📊"},"achievements":{"title":"成就系统","description":"通过收集卡片、聊天和记录，解锁独一无二的成就。","icon":"🏆"}}},"users":{"title":"适合人群","tags":[{"title":"热爱记录生活","icon":"📒"},{"title":"注重情绪管理","icon":"❤️"},{"title":"生活节奏快","icon":"⚡"},{"title":"寻求缓解压力","icon":"🍃"},{"title":"渴望倾诉陪伴","icon":"🧸"},{"title":"追求内心平静","icon":"🧘"}]},"productIntro":{"mainTitle":"核心功能","sections":[{"title":"聊聊与自我梳理（AI 生成）","items":["在平静、支持性的空间中说出你的想法","温柔的提示帮助你命名自己的感受并理解其重要性"]},{"title":"树洞（私密倾诉）","items":["随时将烦恼放入专属“树洞”","无需评判——只是一个让你卸下包袱、继续前行的地方"]},{"title":"情绪卡片","items":["抽取情绪卡片，获得快速洞察与鼓励","温柔的提醒帮助你换个角度继续前行"]},{"title":"照片日记","items":["写下日记、拍下一张照片，捕捉此刻的自己","或上传设备中的图片，把回忆串联在一起","创建属于你的情绪、故事与成长时间线"]},{"title":"每周洞察","items":["基于你的应用行为（如写日记/树洞）生成简要总结","帮助你轻松发现模式——无压力"]}],"noteTitle":"重要提示","noteBody":"心窝森林提供温柔的 AI 内容与日记工具，但并非医疗应用，不提供诊断或治疗。如你处于危险中或有自伤念头，请立即联系当地紧急救援或可信赖的专业人士。"}},"footer":{"privacyPolicy":"隐私政策","termsOfService":"服务条款"}}'))},2292,e=>{e.v(JSON.parse('{"home":{"heroTitle":"Encoflow Digital Studio","features":{"innovation":{"title":"創新驅動","desc":"把最前沿的 AI 技術融入每個創意專案，突破既有邊界，創造更多可能。"},"design":{"title":"設計美學","desc":"追求極致的視覺體驗，每個像素都經過精心打磨，呈現令人驚豔的美感。"},"quality":{"title":"品質保證","desc":"嚴格的品質控管流程，每個作品都代表我們對卓越的不懈追求。"},"experience":{"title":"以體驗為核心","desc":"從使用者路徑到互動細節持續打磨，讓產品更順手、更清楚、更好用。"},"maintenance":{"title":"持續維護","desc":"上線不止於交付，持續修復、優化與迭代，讓體驗長期穩定成長。"},"security":{"title":"安全與隱私","desc":"保護您的資料是我們的首要任務。我們採用業界領先的安全措施，確保您的資訊安全且機密。"}},"feedbackButton":"提交回饋","feedbackCardTitle":"向我們反饋","feedbackCardDesc":["歡迎隨時向我們回饋問題或投遞您的想法與建議。我們會認真閱讀每一則回饋，持續優化迭代，把產品做得更好。您可以分享使用過程中遇到的阻礙與期待，也可以提出您希望未來新增或優化的方向。我們也很歡迎您附上使用情境、截圖或重現步驟，這會幫助我們更快定位與改進。","若您有意願與我們進行創意合作或加入團隊，歡迎隨時與我們聯繫。"]},"carousel":{"items":{"pailiti":{"title":"3D-拍立體","subtitle":"讓你能從一張圖片快速生成可用的 3D 模型，在手機上即時預覽，並輕鬆匯出為 GLB/STL 格式。無需任何 3D 基礎，真正做到所見即所得。","description":"拍照 → 生成 → 預覽 → 匯出，一次搞定。","details":{"intro":"3D-拍立體 讓你能從一張圖片快速生成可用的 3D 模型，在手機上即時預覽，並輕鬆匯出為 GLB/STL。無需任何 3D 基礎，真正做到所見即所得。","featureTitle":"核心功能","items":["一鍵圖片轉 3D：匯入照片或圖片即可自動生成 3D 模型（很適合做可編輯草模/草稿，方便快速迭代與後續精修）。","所見即所得預覽：內建 3D 檢視器，支援旋轉、縮放與多種環境光預設。","多種匯出格式：可匯出 GLB/STL，方便在主流引擎與工具中繼續編輯。","任務佇列與歷史：自動記錄生成任務，隨時下載與管理。","本地快取：生成的模型可離線查看。","多語介面：支援多種語言。"]}},"koala":{"title":"心窩森林","subtitle":"一個舒適、私密的空間，讓你的感受得以呼吸。\\n需要陪伴時可以聊天，需要清晰時可以寫作，並使用溫柔的工具釋放內心的鬱結。","description":"讓情緒輕輕落腳的地方。","details":{"sections":[{"title":"🗣️ 聊聊與自我梳理（AI 生成）","items":["在平靜、支持性的空間裡，把想法說出來","溫柔的提示，幫你說清自己在感受什麼、為何重要"]},{"title":"🕳️ 樹洞（私密傾訴）","items":["隨時把煩惱丟進專屬「樹洞」","不評判，只負責承載，讓你輕裝繼續"]},{"title":"🎴 情緒卡片","items":["抽取情緒卡，獲得快速洞察與鼓勵","小小提醒，幫你換個角度繼續前行"]},{"title":"📓 照片日記","items":["想記錄時寫下日記，並拍一張照片定格當下","也可以從裝置上傳照片，把回憶放在一起","建立屬於你的情緒、故事與成長時間線"]},{"title":"📊 每週洞察","items":["基於應用內活動的簡要總結（例如寫日記/樹洞趨勢）","幫助你輕鬆發現模式——不帶壓力"]}]}}}},"pailitiPage":{"title":"3D-拍立體","subtitle":"從一張圖片快速生成可用的 3D 模型，在手機上即時預覽，並輕鬆匯出為 GLB/STL。無需任何 3D 基礎，真正做到所見即所得。","description":"3D-拍立體 是一款創新應用，利用先進 AI 技術將你的 2D 圖片轉為高品質 3D 模型。只要上傳一張照片，演算法就會自動產生精細模型，你可以即時預覽並匯出，用於各種專案。無論你是設計師、開發者或愛好者，3D-拍立體 都能簡化創作流程。","storyIntro":{"title":"3D-拍立體 篇","paragraphs":["從最初的一個靈感，到真的能在手機上動起來，這一路其實經歷了不少。有卡關、有失誤，也有那些小小的喜悅。","對我來說，它不只是一個 App，更像是一段「把想法變成現實」的學習旅程。也許還不完美，但每個細節都包含著我們的用心。希望你也能感受到那份認真與溫度。"]},"features":{"title":"特性展示","items":{"ai_modeling":{"title":"AI 智慧建模","description":"先進 AI 演算法，一鍵將 2D 圖片轉成高品質 3D 模型。","icon":"🎨"},"export":{"title":"多格式匯出","description":"支援 GLB、STL 等主流 3D 格式，滿足不同場景需求。","icon":"📦"},"preview":{"title":"線上預覽","description":"即時 360° 檢視模型，多種環境光預設可切換。","icon":"👁️"},"optimization":{"title":"AI 優化","description":"智慧修圖與風格化，讓生成效果更穩定。","icon":"🔄"},"share":{"title":"一鍵分享","description":"輕鬆分享 3D 作品到社群或團隊。","icon":"🌐"},"fast":{"title":"極速生成","description":"最佳化雲端流程，快速取得可用 3D 模型。","icon":"⚡"}}},"users":{"title":"適用人群","tags":[{"title":"熱愛遊戲創作","icon":"🎮"},{"title":"痴迷三維世界","icon":"🌍"},{"title":"構想未來空間","icon":"🚀"},{"title":"追求極致體驗","icon":"💎"},{"title":"享受建模樂趣","icon":"🛠️"},{"title":"渴望高效工具","icon":"⚡"},{"title":"探索創新教學","icon":"🎓"}]},"productIntro":{"sectionTitle":"核心功能","items":["一鍵圖片轉 3D：匯入照片或圖片即可自動生成 3D 模型，快速迭代與後續精修。","所見即所得預覽：內建 3D 檢視器，支援旋轉、縮放與多種環境光預設。","多種匯出格式：可匯出 GLB/STL，方便在主流引擎與切片軟體中繼續編輯。","任務佇列與歷史：自動記錄生成任務，隨時下載與管理。","本地快取：生成的模型可離線查看。","多語介面：支援中文、英文、馬來語、日語、韓語等多種語言。"],"noteTitle":"重要提示","noteBody":"本應用側重於快速一鍵生成可編輯的基礎模型。受限於自動化生成技術，結果可能難以達到手工建模的超精細細節。如需更高精度與更佳拓撲，建議在 3D 編輯軟體中進一步優化。"}},"koalaPage":{"title":"心窩森林","subtitle":"讓情緒輕輕落腳的地方。","description":"Koala Haventree 是一款獨特的手機遊戲，提供寧靜舒適的空間讓你放鬆與自我反思。在這個和平的世界裡，你可以種植自己的「情緒樹」，與溫柔的森林生物互動，打造個人化避風港。以舒緩的藝術風格與安定的玩法，幫助你在日常喧囂中找回片刻平靜。","storyIntro":{"title":"心窩森林 篇","paragraphs":["這次是我們首次嘗試打磨一個帶有情感的 AI 應用。過程中，我們花最多力氣的，其實不是「讓它更會說」，而是讓它更懂分寸、更人性化，更能接住你的情緒、讓你安心傾訴。","你可以按需切換不同角色，讓它用更像真人的語氣來陪你聊天：會陪你開玩笑，也會拿捏好分寸——該多說一句時不缺席，該安靜陪著時不打擾。我們常常停下來反問自己：它是在陪伴你，還是在打擾你？所以很多選擇不是為了做得「更多」，而是以陪伴作為核心出發點：在該出現的時候出現、該安靜的時候安靜。","我們一直想守住一件事：製作一款了解你，但不替你下結論；只會在你需要的時候，給你一個安靜、舒服、能發洩、能傾訴、也能記錄心情的地方。"]},"features":{"title":"功能亮點","items":{"emotion_card":{"title":"情緒抽卡","description":"抽取你的專屬情緒卡片，探索內心的每一次波動。","icon":"🃏"},"ai_chat":{"title":"AI 聊天","description":"隨時與可愛的無尾熊伙伴傾訴，分享你的喜怒哀樂。","icon":"💬"},"venting_hole":{"title":"發洩樹洞","description":"把不愉快和秘密安心交給樹洞，讓心靈得到釋放。","icon":"🌳"},"diary":{"title":"寫日記","description":"記錄每天的生活點滴與心情故事，珍藏專屬回憶。","icon":"✍️"},"ai_report":{"title":"AI 報告","description":"根據你的記錄生成情緒報告，幫助你更了解自己。","icon":"📊"},"achievements":{"title":"成就系統","description":"透過收集卡片、聊天與記錄，解鎖獨一無二的成就。","icon":"🏆"}}},"users":{"title":"適合人群","tags":[{"title":"熱愛記錄生活","icon":"📒"},{"title":"注重情緒管理","icon":"❤️"},{"title":"生活節奏快","icon":"⚡"},{"title":"尋求緩解壓力","icon":"🍃"},{"title":"渴望傾訴陪伴","icon":"🧸"},{"title":"追求內心平靜","icon":"🧘"}]},"productIntro":{"mainTitle":"核心功能","sections":[{"title":"聊聊與自我梳理（AI 生成）","items":["在平靜、支持的空間裡說出你的想法","溫柔的提示幫你命名自己的感受並理解其重要性"]},{"title":"樹洞（私密傾訴）","items":["隨時把煩惱投入專屬「樹洞」","不帶評斷——只是幫你卸下心頭重擔並繼續前進的地方"]},{"title":"情緒卡片","items":["抽取情緒卡片，快速得到洞察與鼓勵","小小提醒幫你換個角度繼續前行"]},{"title":"照片日記","items":["寫日記、拍照，記下想紀錄的當下","或上傳裝置照片，把回憶串在一起","建立屬於你的情緒、故事與成長時間軸"]},{"title":"每週洞察","items":["根據你的應用行為（如寫日記/樹洞）生成簡要總結","幫助你輕鬆發現模式——不帶壓力"]}],"noteTitle":"重要提示","noteBody":"心窩森林提供溫柔的 AI 內容與日記工具，並非醫療應用，無法提供診斷或治療。如你處於危險或有自傷念頭，請立即聯繫當地緊急救援或可信賴的專業人士。"}},"footer":{"privacyPolicy":"隱私政策","termsOfService":"服務條款"}}'))}]);